--
-- Name: admin_override_community_ai_status(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_override_community_ai_status(p_action_id uuid, p_new_status text, p_note text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS public.community_ai_actions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text := current_setting('role', true);
  v_row community_ai_actions;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND COALESCE(v_caller_role, '') NOT IN ('service_role', 'postgres') THEN
    RAISE EXCEPTION 'admin_override_forbidden: caller role %, expected service_role', v_caller_role
      USING ERRCODE = '42501';
  END IF;

  IF p_new_status NOT IN (
    'pending','approved','dispatched','acknowledged','executing',
    'executed','sent_unverified','failed','skipped','blocked','scheduled'
  ) THEN
    RAISE EXCEPTION 'invalid status: %', p_new_status USING ERRCODE = '22023';
  END IF;

  UPDATE community_ai_actions
  SET    status                     = p_new_status,
         execution_result           = COALESCE(execution_result, '{}'::jsonb)
                                      || jsonb_build_object(
                                           'source',            'admin_override',
                                           'override_note',     p_note,
                                           'override_at',       NOW(),
                                           'override_actor',    p_actor_user_id
                                         ),
         dispatch_lease_id          = NULL,
         dispatch_lease_expires_at  = NULL,
         dispatch_lease_holder_id   = NULL,
         dispatch_acknowledged_at   = NULL,
         updated_at                 = NOW()
  WHERE  id = p_action_id
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'admin_override_not_found: action_id %', p_action_id
      USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO audit_logs (actor_user_id, action, metadata, created_at)
  VALUES (
    p_actor_user_id,
    'COMMUNITY_AI_ADMIN_OVERRIDE',
    jsonb_build_object(
      'action_id',   p_action_id,
      'new_status',  p_new_status,
      'note',        p_note
    ),
    NOW()
  );

  RETURN v_row;
END;
$$;


--
-- Name: advance_job_execution(text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_job_execution(p_execution_hash text, p_status text, p_billing_operation_id uuid DEFAULT NULL::uuid, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row public.job_execution_registry%ROWTYPE;
BEGIN
  UPDATE public.job_execution_registry
    SET status = p_status,
        billing_operation_id = COALESCE(p_billing_operation_id, billing_operation_id),
        error_message = p_error,
        completed_at = CASE WHEN p_status IN ('completed','released','orphan_reaped','duplicate_blocked')
                            THEN COALESCE(completed_at, now())
                            ELSE completed_at END,
        last_seen_at = now()
    WHERE execution_hash = p_execution_hash
    RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'JER_NOT_FOUND: execution_hash=%', p_execution_hash;
  END IF;

  RETURN jsonb_build_object('id', v_row.id, 'status', v_row.status);
END;
$$;


--
-- Name: advance_payment_provider_event_state(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_payment_provider_event_state(p_event_id uuid, p_status text, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_state public.payment_provider_event_state%ROWTYPE;
BEGIN
  IF p_event_id IS NULL THEN
    RAISE EXCEPTION 'event_id is required';
  END IF;
  IF p_status NOT IN ('recorded', 'processed', 'duplicate', 'failed', 'requeued') THEN
    RAISE EXCEPTION 'invalid status %', p_status;
  END IF;

  INSERT INTO public.payment_provider_event_state (provider_event_pk, processing_status, processed_at, error_message)
  VALUES (p_event_id, p_status, CASE WHEN p_status IN ('processed','duplicate') THEN now() ELSE NULL END, p_error)
  ON CONFLICT (provider_event_pk) DO UPDATE
    SET processing_status = EXCLUDED.processing_status,
        processed_at      = COALESCE(EXCLUDED.processed_at, public.payment_provider_event_state.processed_at),
        error_message     = EXCLUDED.error_message,
        retry_count       = public.payment_provider_event_state.retry_count + 1,
        updated_at        = now()
    RETURNING * INTO v_state;

  RETURN jsonb_build_object(
    'provider_event_pk', v_state.provider_event_pk,
    'processing_status', v_state.processing_status,
    'processed_at',      v_state.processed_at,
    'retry_count',       v_state.retry_count
  );
END;
$$;


--
-- Name: ai_message_drafts_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_message_drafts_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  thread_platform TEXT;
BEGIN
  -- 1. Platform must match the thread's platform (no cross-channel drift)
  SELECT platform INTO thread_platform
  FROM engagement_threads WHERE id = NEW.thread_id;

  IF thread_platform IS NULL THEN
    RAISE EXCEPTION 'AI_DRAFT_THREAD_NOT_FOUND: thread % does not exist', NEW.thread_id;
  END IF;

  IF NEW.platform IS DISTINCT FROM thread_platform THEN
    RAISE EXCEPTION 'AI_DRAFT_PLATFORM_MISMATCH: draft.platform=% must match thread.platform=%',
      NEW.platform, thread_platform;
  END IF;

  -- 2. Transition to 'sent' is only allowed FROM 'approved'
  IF NEW.status = 'sent' THEN
    IF TG_OP = 'INSERT' OR OLD.status <> 'approved' THEN
      RAISE EXCEPTION 'AI_DRAFT_SEND_REQUIRES_APPROVAL: status=sent only allowed transitioning from approved (was: %)',
        COALESCE(OLD.status, '<insert>');
    END IF;
    IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL THEN
      RAISE EXCEPTION 'AI_DRAFT_SEND_REQUIRES_APPROVER: approved_by and approved_at must be set before sending';
    END IF;
    IF NEW.sent_at IS NULL THEN
      NEW.sent_at := now();
    END IF;
  END IF;

  -- 3. Auto-stamp approved_at if status flips to 'approved' without it
  IF NEW.status = 'approved' AND NEW.approved_at IS NULL THEN
    NEW.approved_at := now();
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION ai_message_drafts_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ai_message_drafts_guard() IS 'Send guard for ai_message_drafts. Blocks platform mismatch + direct-to-sent transitions.';


--
-- Name: apply_credit_partial_confirm(uuid, uuid, integer, integer, integer, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_credit_partial_confirm(p_org_id uuid, p_hold_txn_id uuid, p_actual_free integer DEFAULT 0, p_actual_incentive integer DEFAULT 0, p_actual_paid integer DEFAULT 0, p_idempotency_key text DEFAULT NULL::text, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_tx_row       credit_transactions%ROWTYPE;
  v_hold         credit_transactions%ROWTYPE;

  v_held_free       int;
  v_held_incentive  int;
  v_held_paid       int;

  v_consume_free    int;
  v_consume_incentive int;
  v_consume_paid    int;

  v_excess_free     int;
  v_excess_incentive int;
  v_excess_paid     int;

  v_release_free    int;
  v_release_incentive int;
  v_release_paid    int;

  v_wallet          organization_credits%ROWTYPE;
  v_extra_free      int := 0;
  v_extra_incentive int := 0;
  v_extra_paid      int := 0;
  v_shortfall_free  int := 0;
  v_shortfall_incentive int := 0;
  v_shortfall_paid  int := 0;
  v_is_underfunded  boolean := false;

  v_consumed_total  int;
  v_released_total  int;
BEGIN
  -- ── Idempotency ───────────────────────────────────────────────────────────
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    IF FOUND THEN
      RETURN row_to_json(v_tx_row)::jsonb;
    END IF;
  END IF;

  -- ── Load and validate parent HOLD ─────────────────────────────────────────
  SELECT * INTO v_hold
    FROM credit_transactions
   WHERE id = p_hold_txn_id
     AND organization_id = p_org_id
     AND execution_phase = 'hold';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_hold_found: hold_txn_id=% org=%', p_hold_txn_id, p_org_id;
  END IF;

  -- HOLD deltas are stored NEGATIVE (outflow); flip sign to get held amounts
  v_held_free      := ABS(COALESCE(v_hold.free_delta, 0));
  v_held_incentive := ABS(COALESCE(v_hold.incentive_delta, 0));
  v_held_paid      := ABS(COALESCE(v_hold.paid_delta, 0));

  -- Per-category split:
  --   consume = min(actual, held)
  --   excess  = max(actual - held, 0)   -- needs to come from balance
  --   release = held - consume          -- unused reservation returned
  v_consume_free      := LEAST(p_actual_free,      v_held_free);
  v_consume_incentive := LEAST(p_actual_incentive, v_held_incentive);
  v_consume_paid      := LEAST(p_actual_paid,      v_held_paid);

  v_excess_free       := GREATEST(p_actual_free      - v_held_free,      0);
  v_excess_incentive  := GREATEST(p_actual_incentive - v_held_incentive, 0);
  v_excess_paid       := GREATEST(p_actual_paid      - v_held_paid,      0);

  v_release_free      := v_held_free      - v_consume_free;
  v_release_incentive := v_held_incentive - v_consume_incentive;
  v_release_paid      := v_held_paid      - v_consume_paid;

  -- ── Lock wallet and apply ─────────────────────────────────────────────────
  SELECT * INTO v_wallet
    FROM organization_credits
   WHERE organization_id = p_org_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_credit_account: org %', p_org_id;
  END IF;

  -- 1. Consume from reserved (the "CONFIRM" part):
  --    reserved_X -= consume_X
  --    lifetime_consumed += consume_X
  -- 2. Release unused reservation (the "RELEASE" part):
  --    reserved_X -= release_X
  --    balance_X  += release_X
  -- 3. Excess consumption — try to pull from balance; underfunded if insufficient:
  --    take = min(excess, balance_after_release)
  --    balance_X  -= take
  --    lifetime_consumed += take
  --    shortfall_X = excess - take

  -- Apply (1) + (2) first, then compute excess from updated balance
  UPDATE organization_credits SET
    reserved_free      = GREATEST(0, reserved_free      - v_consume_free      - v_release_free),
    reserved_incentive = GREATEST(0, reserved_incentive - v_consume_incentive - v_release_incentive),
    reserved_paid      = GREATEST(0, reserved_paid      - v_consume_paid      - v_release_paid),
    free_balance       = free_balance      + v_release_free,
    incentive_balance  = incentive_balance + v_release_incentive,
    paid_balance       = paid_balance      + v_release_paid,
    lifetime_consumed  = lifetime_consumed + v_consume_free + v_consume_incentive + v_consume_paid,
    updated_at         = NOW()
  WHERE organization_id = p_org_id
  RETURNING * INTO v_wallet;

  -- (3) Excess from balance
  IF v_excess_free > 0 THEN
    v_extra_free     := LEAST(v_excess_free, v_wallet.free_balance);
    v_shortfall_free := v_excess_free - v_extra_free;
  END IF;
  IF v_excess_incentive > 0 THEN
    v_extra_incentive     := LEAST(v_excess_incentive, v_wallet.incentive_balance);
    v_shortfall_incentive := v_excess_incentive - v_extra_incentive;
  END IF;
  IF v_excess_paid > 0 THEN
    v_extra_paid     := LEAST(v_excess_paid, v_wallet.paid_balance);
    v_shortfall_paid := v_excess_paid - v_extra_paid;
  END IF;

  IF (v_extra_free + v_extra_incentive + v_extra_paid) > 0 THEN
    UPDATE organization_credits SET
      free_balance      = free_balance      - v_extra_free,
      incentive_balance = incentive_balance - v_extra_incentive,
      paid_balance      = paid_balance      - v_extra_paid,
      lifetime_consumed = lifetime_consumed + v_extra_free + v_extra_incentive + v_extra_paid,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;
  END IF;

  v_is_underfunded := (v_shortfall_free + v_shortfall_incentive + v_shortfall_paid) > 0;

  v_consumed_total := v_consume_free + v_consume_incentive + v_consume_paid
                    + v_extra_free   + v_extra_incentive   + v_extra_paid;
  v_released_total := v_release_free + v_release_incentive + v_release_paid;

  -- ── Append ledger row ─────────────────────────────────────────────────────
  INSERT INTO credit_transactions (
    organization_id,
    transaction_type,
    credits_delta,
    balance_after,
    reference_type,
    reference_id,
    note,
    performed_by,
    idempotency_key,
    execution_phase,
    parent_transaction_id,
    category,
    free_delta,
    paid_delta,
    incentive_delta,
    is_underfunded,
    created_at
  )
  VALUES (
    p_org_id,
    'deduction',
    -v_consumed_total,
    (v_wallet.free_balance + v_wallet.paid_balance + v_wallet.incentive_balance)
      - v_extra_free - v_extra_incentive - v_extra_paid,
    p_reference_type,
    p_reference_id::uuid,
    COALESCE(p_note, 'confirm_partial') ||
      CASE WHEN v_is_underfunded
           THEN ' [UNDERFUNDED shortfall_total=' ||
                (v_shortfall_free + v_shortfall_incentive + v_shortfall_paid) || ']'
           ELSE '' END,
    p_performed_by,
    p_idempotency_key,
    'confirm_partial',
    p_hold_txn_id,
    'paid',
    -(v_consume_free      + v_extra_free),
    -(v_consume_paid      + v_extra_paid),
    -(v_consume_incentive + v_extra_incentive),
    v_is_underfunded,
    NOW()
  )
  RETURNING * INTO v_tx_row;

  RETURN jsonb_build_object(
    'id',                 v_tx_row.id,
    'consumed_free',      v_consume_free      + v_extra_free,
    'consumed_incentive', v_consume_incentive + v_extra_incentive,
    'consumed_paid',      v_consume_paid      + v_extra_paid,
    'released_free',      v_release_free,
    'released_incentive', v_release_incentive,
    'released_paid',      v_release_paid,
    'shortfall_free',     v_shortfall_free,
    'shortfall_incentive',v_shortfall_incentive,
    'shortfall_paid',     v_shortfall_paid,
    'is_underfunded',     v_is_underfunded,
    'total_consumed',     v_consumed_total,
    'total_released',     v_released_total
  );

EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    RETURN row_to_json(v_tx_row)::jsonb;
END;
$$;


--
-- Name: apply_credit_reservation(uuid, text, integer, integer, integer, text, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_credit_reservation(p_org_id uuid, p_phase text, p_free_amount integer DEFAULT 0, p_incentive_amount integer DEFAULT 0, p_paid_amount integer DEFAULT 0, p_idempotency_key text DEFAULT NULL::text, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_parent_id uuid DEFAULT NULL::uuid, p_category text DEFAULT 'paid'::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_wallet   organization_credits%ROWTYPE;
  v_tx_row   credit_transactions%ROWTYPE;
  v_avail_free      int;
  v_avail_incentive int;
  v_avail_paid      int;
  v_tx_type  text;
  v_free_delta      int := 0;
  v_incentive_delta int := 0;
  v_paid_delta      int := 0;
BEGIN
  -- ── Idempotency: return existing row if key already processed ───────────────
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    IF FOUND THEN
      RETURN row_to_json(v_tx_row)::jsonb;
    END IF;
  END IF;

  -- ── Lock the wallet row for this operation ──────────────────────────────────
  SELECT * INTO v_wallet
    FROM organization_credits
   WHERE organization_id = p_org_id
   FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO organization_credits (organization_id)
    VALUES (p_org_id)
    ON CONFLICT (organization_id) DO NOTHING;

    SELECT * INTO v_wallet
      FROM organization_credits
     WHERE organization_id = p_org_id
     FOR UPDATE;
  END IF;

  -- ── Phase dispatch ──────────────────────────────────────────────────────────

  IF p_phase = 'hold' THEN
    v_avail_free      := GREATEST(0, v_wallet.free_balance      - v_wallet.reserved_free);
    v_avail_incentive := GREATEST(0, v_wallet.incentive_balance - v_wallet.reserved_incentive);
    v_avail_paid      := GREATEST(0, v_wallet.paid_balance      - v_wallet.reserved_paid);

    IF p_free_amount > v_avail_free THEN
      RAISE EXCEPTION 'insufficient free balance: need %, have %', p_free_amount, v_avail_free;
    END IF;
    IF p_incentive_amount > v_avail_incentive THEN
      RAISE EXCEPTION 'insufficient incentive balance: need %, have %', p_incentive_amount, v_avail_incentive;
    END IF;
    IF p_paid_amount > v_avail_paid THEN
      RAISE EXCEPTION 'insufficient paid balance: need %, have %', p_paid_amount, v_avail_paid;
    END IF;

    UPDATE organization_credits SET
      free_balance      = free_balance      - p_free_amount,
      incentive_balance = incentive_balance - p_incentive_amount,
      paid_balance      = paid_balance      - p_paid_amount,
      reserved_free     = reserved_free     + p_free_amount,
      reserved_incentive= reserved_incentive+ p_incentive_amount,
      reserved_paid     = reserved_paid     + p_paid_amount,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'deduction';
    v_free_delta     := -p_free_amount;
    v_incentive_delta:= -p_incentive_amount;
    v_paid_delta     := -p_paid_amount;

  ELSIF p_phase = 'confirm' THEN
    UPDATE organization_credits SET
      reserved_free     = GREATEST(0, reserved_free      - p_free_amount),
      reserved_incentive= GREATEST(0, reserved_incentive - p_incentive_amount),
      reserved_paid     = GREATEST(0, reserved_paid      - p_paid_amount),
      lifetime_consumed = lifetime_consumed + p_free_amount + p_incentive_amount + p_paid_amount,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'deduction';
    v_free_delta     := -p_free_amount;
    v_incentive_delta:= -p_incentive_amount;
    v_paid_delta     := -p_paid_amount;

  ELSIF p_phase = 'release' THEN
    UPDATE organization_credits SET
      free_balance      = free_balance      + p_free_amount,
      incentive_balance = incentive_balance + p_incentive_amount,
      paid_balance      = paid_balance      + p_paid_amount,
      reserved_free     = GREATEST(0, reserved_free      - p_free_amount),
      reserved_incentive= GREATEST(0, reserved_incentive - p_incentive_amount),
      reserved_paid     = GREATEST(0, reserved_paid      - p_paid_amount),
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'refund';
    v_free_delta     := p_free_amount;
    v_incentive_delta:= p_incentive_amount;
    v_paid_delta     := p_paid_amount;

  ELSIF p_phase = 'grant' THEN
    UPDATE organization_credits SET
      free_balance      = free_balance      + p_free_amount,
      incentive_balance = incentive_balance + p_incentive_amount,
      paid_balance      = paid_balance      + p_paid_amount,
      lifetime_purchased= lifetime_purchased + p_free_amount + p_incentive_amount + p_paid_amount,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'purchase';
    v_free_delta     := p_free_amount;
    v_incentive_delta:= p_incentive_amount;
    v_paid_delta     := p_paid_amount;

  ELSIF p_phase = 'expire' THEN
    -- ── CATEGORY GUARD: expire can only drain free_balance ──────────────────
    -- Paid credits never expire. Incentive credits are expired via a separate
    -- controlled path with explicit config opt-in. Any caller that accidentally
    -- passes non-zero values here gets a hard failure, not a silent no-op.
    IF p_incentive_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire phase cannot touch incentive_balance (p_incentive_amount=%)',
        p_incentive_amount;
    END IF;
    IF p_paid_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire phase cannot touch paid_balance (p_paid_amount=%)',
        p_paid_amount;
    END IF;

    -- Only free_balance is reduced. GREATEST(0, ...) prevents going negative.
    UPDATE organization_credits SET
      free_balance = GREATEST(0, free_balance - p_free_amount),
      updated_at   = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type    := 'deduction';
    v_free_delta := -LEAST(p_free_amount, v_wallet.free_balance);

  ELSIF p_phase = 'expire_incentive' THEN
    -- ── Incentive expiry — separate, explicitly named phase ─────────────────
    -- Only callable when the incentive_expiry config row has is_active=true.
    -- Paid credits are never touched here either.
    IF p_paid_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire_incentive phase cannot touch paid_balance (p_paid_amount=%)',
        p_paid_amount;
    END IF;
    IF p_free_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire_incentive phase cannot touch free_balance (p_free_amount=%)',
        p_free_amount;
    END IF;

    UPDATE organization_credits SET
      incentive_balance = GREATEST(0, incentive_balance - p_incentive_amount),
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'deduction';
    v_incentive_delta:= -LEAST(p_incentive_amount, v_wallet.incentive_balance);

  ELSE
    RAISE EXCEPTION 'unknown phase: %', p_phase;
  END IF;

  -- ── Append ledger row ───────────────────────────────────────────────────────
  INSERT INTO credit_transactions (
    organization_id,
    transaction_type,
    credits_delta,
    balance_after,
    reference_type,
    reference_id,
    note,
    performed_by,
    idempotency_key,
    execution_phase,
    parent_transaction_id,
    category,
    free_delta,
    paid_delta,
    incentive_delta,
    created_at
  )
  SELECT
    p_org_id,
    v_tx_type,
    v_free_delta + v_incentive_delta + v_paid_delta,
    oc.free_balance + oc.paid_balance + oc.incentive_balance,
    p_reference_type,
    p_reference_id::uuid,
    p_note,
    p_performed_by,
    p_idempotency_key,
    p_phase,
    p_parent_id,
    p_category,
    v_free_delta,
    v_paid_delta,
    v_incentive_delta,
    NOW()
  FROM organization_credits oc
  WHERE oc.organization_id = p_org_id
  RETURNING * INTO v_tx_row;

  RETURN row_to_json(v_tx_row)::jsonb;

EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    RETURN row_to_json(v_tx_row)::jsonb;
END;
$$;


--
-- Name: apply_credit_transaction_v2(uuid, text, integer, numeric, text, text, text, uuid, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_credit_transaction_v2(p_organization_id uuid, p_transaction_type text, p_credits_delta integer, p_usd_equivalent numeric DEFAULT NULL::numeric, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_execution_phase text DEFAULT 'confirm'::text, p_parent_transaction_id uuid DEFAULT NULL::uuid, p_category text DEFAULT 'paid'::text, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_existing  JSONB;
  v_new_id    UUID;
  v_balance   INT;
  v_balance_after INT;
BEGIN
  -- ── 1. Idempotency: if key already exists, return the existing row ───────────
  IF p_idempotency_key IS NOT NULL THEN
    SELECT row_to_json(t)::JSONB INTO v_existing
    FROM credit_transactions t
    WHERE idempotency_key = p_idempotency_key
    LIMIT 1;

    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  -- ── 2. For confirm/deduction phases: check + lock balance ──────────────────
  IF p_credits_delta < 0 AND p_execution_phase IN ('confirm', 'direct') THEN
    SELECT balance_credits INTO v_balance
    FROM organization_credits
    WHERE organization_id = p_organization_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'no_credit_account: organization % has no credit account', p_organization_id;
    END IF;

    IF v_balance + p_credits_delta < 0 THEN
      RAISE EXCEPTION 'insufficient_credits: need %, have %',
        ABS(p_credits_delta), v_balance;
    END IF;

    v_balance_after := v_balance + p_credits_delta;
  END IF;

  -- ── 3. Insert the transaction row ────────────────────────────────────────────
  INSERT INTO credit_transactions (
    organization_id,
    transaction_type,
    credits_delta,
    balance_after,
    usd_equivalent,
    reference_type,
    reference_id,
    note,
    performed_by,
    idempotency_key,
    execution_phase,
    parent_transaction_id,
    category,
    created_at
  ) VALUES (
    p_organization_id,
    p_transaction_type,
    p_credits_delta,
    v_balance_after,
    p_usd_equivalent,
    p_reference_type,
    p_reference_id::UUID,
    p_note,
    p_performed_by,
    p_idempotency_key,
    p_execution_phase,
    p_parent_transaction_id,
    COALESCE(p_category, 'paid'),
    NOW()
  )
  RETURNING id INTO v_new_id;

  -- ── 4. Mutate balance ONLY for confirm/purchase/direct phases ────────────────
  --       hold    → NO balance change (intent only)
  --       release → NO balance change (hold never deducted)
  --       confirm → balance already checked above; apply delta
  --       purchase/reversal → apply delta (admin grants, refunds)
  IF p_execution_phase IN ('confirm', 'direct')
     OR p_transaction_type IN ('purchase', 'reversal') THEN

    UPDATE organization_credits
    SET
      balance_credits = balance_credits + p_credits_delta,
      updated_at      = NOW()
    WHERE organization_id = p_organization_id;
  END IF;

  -- ── 5. Return the inserted row ────────────────────────────────────────────────
  RETURN (
    SELECT row_to_json(t)::JSONB
    FROM credit_transactions t
    WHERE id = v_new_id
  );

EXCEPTION
  WHEN unique_violation THEN
    -- Race condition: another thread inserted same idempotency_key
    -- Return the winning row
    RETURN (
      SELECT row_to_json(t)::JSONB
      FROM credit_transactions t
      WHERE idempotency_key = p_idempotency_key
      LIMIT 1
    );
END;
$$;


--
-- Name: auth_user_confirmed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_user_confirmed(p_email text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  SELECT COALESCE(
    (SELECT email_confirmed_at IS NOT NULL
     FROM auth.users
     WHERE lower(email) = lower(p_email)
     LIMIT 1),
    false
  );
$$;


--
-- Name: FUNCTION auth_user_confirmed(p_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auth_user_confirmed(p_email text) IS 'Returns true iff auth.users has a confirmed row for this email. Used by /api/auth/signup to short-circuit when Supabase would otherwise silently treat the call as user_repeated_signup.';


--
-- Name: auth_user_has_password(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_user_has_password(p_user_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  SELECT COALESCE(
    (SELECT encrypted_password IS NOT NULL AND encrypted_password <> ''
     FROM auth.users
     WHERE id = p_user_id),
    false
  );
$$;


--
-- Name: cancel_credit_action_approval(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_credit_action_approval(p_approval_id uuid, p_actor uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row public.credit_action_approvals%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.credit_action_approvals
    WHERE id = p_approval_id FOR UPDATE;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'APPROVAL_NOT_FOUND: %', p_approval_id;
  END IF;
  IF v_row.executed_at IS NOT NULL THEN
    RAISE EXCEPTION 'APPROVAL_ALREADY_EXECUTED: cannot cancel after execute';
  END IF;
  IF v_row.status <> 'pending' THEN
    RAISE EXCEPTION 'APPROVAL_NOT_PENDING: status=%', v_row.status;
  END IF;
  IF v_row.proposed_by <> p_actor THEN
    -- only the proposer (or a future cancellation-capable role) can cancel
    RAISE EXCEPTION 'APPROVAL_CANCEL_NOT_ALLOWED: only proposer may cancel';
  END IF;

  UPDATE public.credit_action_approvals
    SET status           = 'cancelled',
        rejection_reason = p_reason,
        rejected_at      = now(),
        rejected_by      = p_actor
    WHERE id = p_approval_id
    RETURNING * INTO v_row;

  RETURN jsonb_build_object('id', v_row.id, 'status', v_row.status);
END;
$$;


--
-- Name: capability_audit_log_block_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capability_audit_log_block_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'capability_audit_log is append-only; %s denied', TG_OP;
END;
$$;


--
-- Name: claim_conversation_memory_rebuild_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_conversation_memory_rebuild_batch(p_limit integer DEFAULT 20) RETURNS TABLE(thread_id uuid, latest_message_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH to_claim AS (
    SELECT q.thread_id
    FROM conversation_memory_rebuild_queue q
    WHERE q.scheduled_at <= now()
      AND (q.claimed_at IS NULL OR q.claimed_at <= now() - interval '60 seconds')
    ORDER BY q.scheduled_at ASC
    LIMIT p_limit
    FOR UPDATE OF q SKIP LOCKED
  )
  UPDATE conversation_memory_rebuild_queue q
  SET claimed_at = now()
  FROM to_claim c
  WHERE q.thread_id = c.thread_id
  RETURNING q.thread_id, q.latest_message_id;
END;
$$;


--
-- Name: claim_creator_execution_lock(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_creator_execution_lock(p_daily_plan_id uuid, p_lock_owner text, p_expected_plan_version integer, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(locked_by text, lease_expires_at timestamp with time zone, attempt_count integer, retry_count integer, max_retries integer, plan_version integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  UPDATE daily_content_plans
     SET locked_by = p_lock_owner,
         lease_expires_at = now() + make_interval(secs => GREATEST(30, LEAST(COALESCE(p_lease_seconds, 300), 900))),
         attempt_count = COALESCE(daily_content_plans.attempt_count, 0) + 1,
         updated_at = now()
   WHERE daily_content_plans.id = p_daily_plan_id
     AND daily_content_plans.plan_version = COALESCE(p_expected_plan_version, 1)
     AND (
       daily_content_plans.locked_by IS NULL
       OR daily_content_plans.lease_expires_at IS NULL
       OR daily_content_plans.lease_expires_at <= now()
       OR daily_content_plans.locked_by = p_lock_owner
     )
  RETURNING daily_content_plans.locked_by,
            daily_content_plans.lease_expires_at,
            daily_content_plans.attempt_count,
            daily_content_plans.retry_count,
            daily_content_plans.max_retries,
            daily_content_plans.plan_version;
END;
$$;


--
-- Name: claim_email_jobs(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_email_jobs(p_worker_id text, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, job_type text, template_key text, payload jsonb, payload_encrypted boolean, recipient_email text, subject text, html text, retry_count integer, max_retries integer, invitation_id uuid, correlation_id text, idempotency_key text, payload_hash text, request_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  WITH picked AS (
    SELECT ej.id
    FROM email_jobs ej
    WHERE ej.status IN ('pending', 'failed')
      AND COALESCE(ej.next_attempt_at, ej.created_at) <= NOW()
      AND ej.retry_count < ej.max_retries
      AND ej.dead_lettered_at IS NULL
      AND (ej.locked_at IS NULL OR ej.locked_at < NOW() - INTERVAL '5 minutes')
    ORDER BY ej.created_at ASC
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  )
  UPDATE email_jobs ej
  SET status     = 'processing',
      locked_at  = NOW(),
      locked_by  = p_worker_id,
      updated_at = NOW()
  FROM picked
  WHERE ej.id = picked.id
  RETURNING
    ej.id,
    ej.job_type,
    ej.template_key,
    ej.payload,
    ej.payload_encrypted,
    ej.recipient_email,
    ej.subject,
    ej.html,
    ej.retry_count,
    ej.max_retries,
    ej.invitation_id,
    ej.correlation_id,
    ej.idempotency_key,
    ej.payload_hash,
    ej.request_id;
END;
$$;


--
-- Name: claim_job_execution(text, text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_job_execution(p_job_id text, p_queue_name text, p_execution_hash text, p_correlation_id text, p_idempotency_key text, p_organization_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row public.job_execution_registry%ROWTYPE;
  v_existing public.job_execution_registry%ROWTYPE;
BEGIN
  IF p_execution_hash IS NULL OR btrim(p_execution_hash) = '' THEN
    RAISE EXCEPTION 'execution_hash is required';
  END IF;

  SELECT * INTO v_existing FROM public.job_execution_registry
    WHERE execution_hash = p_execution_hash
    FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    -- Replay path. Bump retry counter; do not regress terminal status.
    UPDATE public.job_execution_registry
      SET retry_count = v_existing.retry_count + 1,
          last_seen_at = now()
      WHERE id = v_existing.id
      RETURNING * INTO v_row;
    RETURN jsonb_build_object(
      'id',           v_row.id,
      'status',       v_row.status,
      'first_seen',   false,
      'retry_count',  v_row.retry_count,
      'is_terminal',  v_row.status IN ('completed','released','orphan_reaped','duplicate_blocked')
    );
  END IF;

  INSERT INTO public.job_execution_registry (
    job_id, queue_name, organization_id, execution_hash, correlation_id,
    idempotency_key, status, metadata
  ) VALUES (
    p_job_id, p_queue_name, p_organization_id, p_execution_hash, p_correlation_id,
    p_idempotency_key, 'reserved', COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'id',           v_row.id,
    'status',       v_row.status,
    'first_seen',   true,
    'retry_count',  0,
    'is_terminal',  false
  );
END;
$$;


--
-- Name: claim_lead_thread_recompute_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_lead_thread_recompute_batch(p_limit integer DEFAULT 20) RETURNS TABLE(thread_id uuid, organization_id uuid, retry_count integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  lim INTEGER := LEAST(p_limit, 200);
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS _claim_batch (
    thread_id UUID,
    organization_id UUID,
    retry_count INTEGER,
    scheduled_at TIMESTAMPTZ,
    is_expired BOOLEAN
  ) ON COMMIT DROP;

  TRUNCATE _claim_batch;

  -- ORDER BY (claimed_at IS NOT NULL) DESC: expired rows first, prevents starvation
  -- idx_lead_recompute_claim_priority (claimed_at, scheduled_at, retry_count) supports scan
  INSERT INTO _claim_batch (thread_id, organization_id, retry_count, scheduled_at, is_expired)
  SELECT q.thread_id, q.organization_id, q.retry_count, q.scheduled_at, (q.claimed_at IS NOT NULL)
  FROM lead_thread_recompute_queue q
  WHERE q.scheduled_at <= NOW()
    AND (q.claimed_at IS NULL OR q.claimed_at <= NOW() - interval '60 seconds')
  ORDER BY (q.claimed_at IS NOT NULL) DESC, q.scheduled_at ASC, q.retry_count ASC
  LIMIT lim
  FOR UPDATE OF q SKIP LOCKED;

  UPDATE lead_thread_recompute_queue q
  SET claimed_at = NOW()
  FROM _claim_batch b
  WHERE q.thread_id = b.thread_id AND q.organization_id = b.organization_id;

  RETURN QUERY SELECT b.thread_id, b.organization_id, b.retry_count
  FROM _claim_batch b
  ORDER BY b.is_expired DESC, b.scheduled_at ASC, b.retry_count ASC;
END;
$$;


--
-- Name: cleanup_lead_thread_recompute_queue_orphans(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_lead_thread_recompute_queue_orphans() RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH deleted AS (
    DELETE FROM lead_thread_recompute_queue q
    WHERE NOT EXISTS (
      SELECT 1 FROM engagement_threads t WHERE t.id = q.thread_id
    )
    OR NOT EXISTS (
      SELECT 1 FROM companies c WHERE c.id = q.organization_id
    )
    RETURNING 1
  )
  SELECT COUNT(*)::INTEGER FROM deleted;
$$;


--
-- Name: configure_domain_reminder_cron(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.configure_domain_reminder_cron(p_url text, p_cron_secret text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE
  v_url_id    uuid;
  v_secret_id uuid;
BEGIN
  IF p_url IS NULL OR length(trim(p_url)) = 0 THEN
    RAISE EXCEPTION 'configure_domain_reminder_cron: p_url is required';
  END IF;

  SELECT id INTO v_url_id
  FROM vault.decrypted_secrets
  WHERE name = 'domain_reminder_cron_url'
  LIMIT 1;
  IF v_url_id IS NULL THEN
    PERFORM vault.create_secret(p_url, 'domain_reminder_cron_url',
      'URL pg_cron POSTs to every 5 minutes for domain reminders');
  ELSE
    PERFORM vault.update_secret(v_url_id, p_url, 'domain_reminder_cron_url', NULL);
  END IF;

  IF p_cron_secret IS NOT NULL AND length(trim(p_cron_secret)) > 0 THEN
    SELECT id INTO v_secret_id
    FROM vault.decrypted_secrets
    WHERE name = 'domain_reminder_cron_secret'
    LIMIT 1;
    IF v_secret_id IS NULL THEN
      PERFORM vault.create_secret(p_cron_secret, 'domain_reminder_cron_secret',
        'Bearer secret sent in the Authorization header to /api/internal/process-reminders');
    ELSE
      PERFORM vault.update_secret(v_secret_id, p_cron_secret, 'domain_reminder_cron_secret', NULL);
    END IF;
  END IF;
END $$;


--
-- Name: FUNCTION configure_domain_reminder_cron(p_url text, p_cron_secret text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.configure_domain_reminder_cron(p_url text, p_cron_secret text) IS 'One-shot: register the URL + bearer secret used by the domain-reminder cron. Run after migration applies. Idempotent — rerunning rotates the values.';


--
-- Name: content_publish_snapshots_guard_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_publish_snapshots_guard_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.snapshot_id          IS DISTINCT FROM OLD.snapshot_id
     OR NEW.publish_contract_id  IS DISTINCT FROM OLD.publish_contract_id
     OR NEW.publish_version_hash IS DISTINCT FROM OLD.publish_version_hash
     OR NEW.idempotency_key      IS DISTINCT FROM OLD.idempotency_key
     OR NEW.snapshot_payload     IS DISTINCT FROM OLD.snapshot_payload
     OR NEW.contract_payload     IS DISTINCT FROM OLD.contract_payload
  THEN
    RAISE EXCEPTION 'content_publish_snapshots: immutable snapshot/contract columns cannot be updated';
  END IF;
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;


--
-- Name: create_organization_credits_on_company_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_organization_credits_on_company_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
  BEGIN
    INSERT INTO organization_credits (
      organization_id,
