      paid_balance,
      incentive_balance,
      lifetime_purchased,
      lifetime_consumed,
      credit_rate_usd,
      created_at,
      updated_at
    ) VALUES (
      NEW.id,
      0, 0, 0, 0, 0,
      0.001,
      NOW(),
      NOW()
    )
    ON CONFLICT (organization_id) DO NOTHING;
    RETURN NEW;
  END;
  $$;


