--
-- Name: current_company_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_company_id() RETURNS uuid
    LANGUAGE sql STABLE
    AS $_$
  select
    case
      when coalesce(auth.jwt() ->> 'company_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        then (auth.jwt() ->> 'company_id')::uuid
      else null
    end
$_$;


--
-- Name: delete_intelligence_signals_older_than_365_days(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_intelligence_signals_older_than_365_days() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  WITH deleted AS (
    DELETE FROM intelligence_signals
    WHERE detected_at < (now() - INTERVAL '365 days')
    RETURNING id
  )
  SELECT count(*)::INTEGER FROM deleted INTO deleted_count;
  RETURN deleted_count;
END;
$$;


--
-- Name: disable_company_cascade(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disable_company_cascade(p_company_id uuid, p_actor uuid, p_reason text) RETURNS TABLE(affected_users integer, revoked_roles integer, revoked_sessions integer)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_now              TIMESTAMPTZ := NOW();
  v_affected_users   INTEGER     := 0;
  v_revoked_roles    INTEGER     := 0;
  v_revoked_sessions INTEGER     := 0;
BEGIN
  IF p_company_id IS NULL THEN
    RAISE EXCEPTION 'DISABLE_COMPANY_CASCADE_NULL_COMPANY';
  END IF;
  IF p_reason IS NULL OR LENGTH(TRIM(p_reason)) = 0 THEN
    RAISE EXCEPTION 'DISABLE_COMPANY_CASCADE_MISSING_REASON';
  END IF;

  UPDATE companies
    SET status = 'inactive'
    WHERE id = p_company_id;

  -- Lock + flip every active membership; capture user_ids for cascade.
  WITH affected AS (
    UPDATE user_company_roles
      SET status = 'inactive',
          deactivated_at = v_now,
          updated_at = v_now
      WHERE company_id = p_company_id
        AND status = 'active'
      RETURNING user_id
  )
  SELECT COUNT(*) INTO v_revoked_roles FROM affected;

  -- Compute distinct user ids in a subsequent statement (Postgres CTE
  -- limitation around mixing INSERT/UPDATE return + reuse).
  WITH affected_users AS (
    SELECT DISTINCT user_id
    FROM user_company_roles
    WHERE company_id = p_company_id
      AND status = 'inactive'
      AND deactivated_at = v_now
  ),
  bumped AS (
    UPDATE users
      SET session_revoked_after = v_now,
          updated_at = v_now
      WHERE id IN (SELECT user_id FROM affected_users)
      RETURNING id
  ),
  revoked AS (
    UPDATE auth_sessions
      SET revoked_at = v_now,
          revocation_reason = p_reason
      WHERE user_id IN (SELECT user_id FROM affected_users)
        AND revoked_at IS NULL
      RETURNING id
  )
  SELECT
    (SELECT COUNT(*) FROM bumped),
    (SELECT COUNT(*) FROM revoked)
  INTO v_affected_users, v_revoked_sessions;

  RETURN QUERY SELECT v_affected_users, v_revoked_roles, v_revoked_sessions;
END;
$$;


--
-- Name: enforce_community_ai_executor_writes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_community_ai_executor_writes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_source text;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  -- Terminal success transitions require executor provenance.
  IF NEW.status IN ('executed', 'sent_unverified') THEN
    v_source := COALESCE(NEW.execution_result->>'source', '');
    IF NEW.execution_correlation_id IS NULL AND v_source NOT IN ('executor', 'admin_override') THEN
      RAISE EXCEPTION 'executor_only_write: transition to % requires execution_correlation_id (actionId=%)',
        NEW.status, NEW.id
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- Terminal failure transitions require either a correlation id or an
  -- explicit system source (reaper / DLQ flusher / admin override).
  IF NEW.status = 'failed' THEN
    v_source := COALESCE(NEW.execution_result->>'source', '');
    IF NEW.execution_correlation_id IS NULL
       AND v_source NOT IN ('lease_reaper', 'executor', 'admin_override')
    THEN
      RAISE EXCEPTION 'executor_only_write: transition to failed requires execution_correlation_id OR execution_result.source in (lease_reaper, executor, admin_override) (actionId=%)',
        NEW.id
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enhance_weekly_content_with_ai(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enhance_weekly_content_with_ai(campaign_uuid uuid, week_num integer, enhancement_prompt text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  week_content jsonb;
  refinement_id uuid;
BEGIN
  SELECT jsonb_agg(to_jsonb(cp)) INTO week_content
  FROM public.content_plans cp
  WHERE cp.campaign_id = campaign_uuid
    AND cp.week_number = week_num;

  INSERT INTO public.weekly_content_refinements (
    campaign_id, week_number, theme, focus_area, original_content,
    ai_enhanced_content, finalized_content, refinement_status,
    ai_enhancement_applied, ai_enhancement_notes
  ) VALUES (
    campaign_uuid,
    week_num,
    COALESCE((SELECT theme FROM public.content_plans WHERE campaign_id = campaign_uuid AND week_number = week_num LIMIT 1), 'Week ' || week_num::text),
    COALESCE((SELECT focus_area FROM public.content_plans WHERE campaign_id = campaign_uuid AND week_number = week_num LIMIT 1), ''),
    COALESCE(week_content, '[]'::jsonb),
    '{}'::jsonb,
    COALESCE(week_content, '[]'::jsonb),
    'ai-enhanced',
    true,
    COALESCE(enhancement_prompt, 'AI enhancement applied')
  )
  ON CONFLICT (campaign_id, week_number)
  DO UPDATE SET
    refinement_status = 'ai-enhanced',
    ai_enhancement_applied = true,
    ai_enhancement_notes = EXCLUDED.ai_enhancement_notes,
    updated_at = now()
  RETURNING id INTO refinement_id;

  UPDATE public.content_plans
  SET refinement_status = 'ai-enhanced',
      ai_suggestions = jsonb_build_object('enhancement_applied', true, 'enhanced_at', now()),
      updated_at = now()
  WHERE campaign_id = campaign_uuid
    AND week_number = week_num;

  RETURN jsonb_build_object('refinement_id', refinement_id, 'status', 'ai-enhanced');
END;
$$;


--
-- Name: expire_org_free_credits(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_org_free_credits(p_org_id uuid, p_amount integer, p_note text DEFAULT 'free credit expiry'::text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_actual int;
BEGIN
  SELECT LEAST(p_amount, free_balance) INTO v_actual
    FROM organization_credits
   WHERE organization_id = p_org_id
   FOR UPDATE;

  IF v_actual IS NULL OR v_actual <= 0 THEN
    RETURN 0;
  END IF;

  UPDATE organization_credits SET
    free_balance = free_balance - v_actual,
    updated_at   = NOW()
  WHERE organization_id = p_org_id;

  RETURN v_actual;
END;
$$;


--
-- Name: extend_creator_execution_lock(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extend_creator_execution_lock(p_daily_plan_id uuid, p_lock_owner text, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(locked_by text, lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  UPDATE daily_content_plans
     SET lease_expires_at = now() + make_interval(secs => GREATEST(30, LEAST(COALESCE(p_lease_seconds, 300), 900))),
         updated_at = now()
   WHERE daily_content_plans.id = p_daily_plan_id
     AND daily_content_plans.locked_by = p_lock_owner
     AND daily_content_plans.lease_expires_at IS NOT NULL
     AND daily_content_plans.lease_expires_at > now()
  RETURNING daily_content_plans.locked_by,
            daily_content_plans.lease_expires_at;
END;
$$;


--
-- Name: finalize_email_job(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_email_job(p_job_id uuid, p_status text, p_error text DEFAULT NULL::text, p_provider_message_id text DEFAULT NULL::text, p_next_attempt_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_job        email_jobs%ROWTYPE;
  v_event_type TEXT;
  v_new_retry  INTEGER;
BEGIN
  SELECT * INTO v_job FROM email_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'EMAIL_JOB_NOT_FOUND';
  END IF;

  IF p_status = 'sent' THEN
    v_new_retry := v_job.retry_count;
    v_event_type := 'sent';
    UPDATE email_jobs
      SET status          = 'sent',
          sent_at         = NOW(),
          last_error      = NULL,
          last_attempt_at = NOW(),
          locked_at       = NULL,
          locked_by       = NULL,
          updated_at      = NOW()
      WHERE id = p_job_id;

  ELSIF p_status = 'failed' THEN
    v_new_retry := v_job.retry_count + 1;
    v_event_type := 'failed';
    UPDATE email_jobs
      SET status          = 'failed',
          last_error      = p_error,
          retry_count     = v_new_retry,
          next_attempt_at = p_next_attempt_at,
          last_attempt_at = NOW(),
          locked_at       = NULL,
          locked_by       = NULL,
          updated_at      = NOW()
      WHERE id = p_job_id;

  ELSIF p_status = 'dead' THEN
    v_new_retry := v_job.retry_count + 1;
    v_event_type := 'dead_lettered';
    UPDATE email_jobs
      SET status            = 'dead',
          dead_lettered_at  = NOW(),
          last_error        = p_error,
          retry_count       = v_new_retry,
          last_attempt_at   = NOW(),
          locked_at         = NULL,
          locked_by         = NULL,
          updated_at        = NOW()
      WHERE id = p_job_id;

  ELSE
    RAISE EXCEPTION 'INVALID_FINALIZE_STATUS:%', p_status;
  END IF;

  INSERT INTO email_events (
    job_id,
    invitation_id,
    recipient_email,
    template_key,
    event_type,
    provider_message_id,
    failure_reason,
    retry_count,
    correlation_id
  ) VALUES (
    p_job_id,
    v_job.invitation_id,
    v_job.recipient_email,
    v_job.template_key,
    v_event_type,
    p_provider_message_id,
    p_error,
    v_new_retry,
    v_job.correlation_id
  );
END;
$$;


--
-- Name: finalize_weekly_content(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_weekly_content(campaign_uuid uuid, week_num integer, finalization_notes text DEFAULT NULL::text, finalized_by_uuid uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  refinement_id uuid;
BEGIN
  UPDATE public.weekly_content_refinements
  SET refinement_status = 'finalized',
      finalized = true,
      finalization_notes = COALESCE(finalization_notes, 'Weekly content finalized'),
      finalized_by = finalized_by_uuid,
      finalized_at = now(),
      updated_at = now()
  WHERE campaign_id = campaign_uuid
    AND week_number = week_num
  RETURNING id INTO refinement_id;

  UPDATE public.content_plans
  SET refinement_status = 'finalized',
      finalization_notes = COALESCE(finalization_notes, 'Weekly content finalized'),
      finalized_at = now(),
      updated_at = now()
  WHERE campaign_id = campaign_uuid
    AND week_number = week_num;

  RETURN jsonb_build_object('refinement_id', refinement_id, 'status', 'finalized');
END;
$$;


--
-- Name: flush_community_ai_metric_dlq(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flush_community_ai_metric_dlq(p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_claimed integer := 0;
  v_flushed integer := 0;
  v_remaining integer := 0;
  r RECORD;
BEGIN
  FOR r IN
    SELECT id, organization_id, action_id, correlation_id, event_type, platform,
           action_type, execution_mode, metadata, retry_count
    FROM   community_ai_metric_dlq
    WHERE  next_retry_at <= NOW()
      AND  retry_count < 10
    ORDER BY next_retry_at ASC
    LIMIT  p_limit
    FOR UPDATE SKIP LOCKED
  LOOP
    v_claimed := v_claimed + 1;
    BEGIN
      INSERT INTO community_ai_execution_metric_events (
        organization_id, action_id, correlation_id, event_type, platform,
        action_type, execution_mode, metadata
      ) VALUES (
        r.organization_id, r.action_id, r.correlation_id, r.event_type, r.platform,
        r.action_type, r.execution_mode, r.metadata
      );
      DELETE FROM community_ai_metric_dlq WHERE id = r.id;
      v_flushed := v_flushed + 1;
    EXCEPTION WHEN OTHERS THEN
      -- Exponential backoff: 2^retry_count seconds, capped at 1 hour.
      UPDATE community_ai_metric_dlq
      SET    retry_count   = retry_count + 1,
             last_error    = substring(SQLERRM, 1, 500),
             next_retry_at = NOW() + LEAST(INTERVAL '1 hour',
                                           (2 ^ LEAST(retry_count + 1, 12)) * INTERVAL '1 second'),
             updated_at    = NOW()
      WHERE  id = r.id;
    END;
  END LOOP;

  SELECT COUNT(*) INTO v_remaining FROM community_ai_metric_dlq WHERE retry_count < 10;

  RETURN jsonb_build_object(
    'claimed',   v_claimed,
    'flushed',   v_flushed,
    'remaining', v_remaining,
    'flushed_at', NOW()
  );
END;
$$;


--
-- Name: free_credits_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.free_credits_summary() RETURNS TABLE(total_credits_given bigint, total_recipients bigint, pending_requests bigint, approved_this_month bigint, manual_grants_total bigint, claims_total bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    (SELECT COALESCE(SUM(credits_granted),0) FROM free_credit_claims)
      + (SELECT COALESCE(SUM(credits_amount),0) FROM manual_credit_grants)
      + (SELECT COALESCE(SUM(COALESCE(credits_granted_amount,0)),0) FROM access_requests WHERE status='approved')
    AS total_credits_given,

    (SELECT COUNT(DISTINCT user_id) FROM free_credit_profiles)
    AS total_recipients,

    (SELECT COUNT(*) FROM access_requests WHERE status='pending')
    AS pending_requests,

    (SELECT COUNT(*) FROM access_requests
     WHERE status='approved' AND reviewed_at >= date_trunc('month', now()))
    AS approved_this_month,

    (SELECT COUNT(*) FROM manual_credit_grants)
    AS manual_grants_total,

    (SELECT COUNT(*) FROM free_credit_claims)
    AS claims_total;
$$;


--
-- Name: get_12_week_campaign_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_12_week_campaign_overview(campaign_uuid uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    result JSONB;
    week_data JSONB;
BEGIN
    SELECT jsonb_build_object(
        'campaign_id', c.id,
        'campaign_name', c.name,
        'campaign_description', c.description,
        'start_date', c.start_date,
        'end_date', c.end_date,
        'status', c.status,
        'current_stage', c.current_stage,
        'weeks', (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'week_number', w.week_number,
                    'theme', w.theme,
                    'focus_area', w.focus_area,
                    'refinement_status', w.refinement_status,
                    'ai_enhanced', w.ai_enhancement_applied,
                    'manually_edited', w.manual_edits_applied,
                    'finalized', w.finalized,
                    'daily_populated', w.daily_plan_populated,
                    'content_count', COALESCE(cp_count.count, 0),
                    'daily_plans_count', COALESCE(dcp_count.count, 0),
                    'week_start_date', c.start_date + INTERVAL '1 week' * (w.week_number - 1),
                    'week_end_date', c.start_date + INTERVAL '1 week' * (w.week_number - 1) + INTERVAL '6 days'
                )
            )
            FROM weekly_content_refinements w
            LEFT JOIN (
                SELECT week_number, COUNT(*) as count 
                FROM content_plans 
                WHERE campaign_id = campaign_uuid 
                GROUP BY week_number
            ) cp_count ON w.week_number = cp_count.week_number
            LEFT JOIN (
                SELECT week_number, COUNT(*) as count 
                FROM daily_content_plans 
                WHERE campaign_id = campaign_uuid 
                GROUP BY week_number
            ) dcp_count ON w.week_number = dcp_count.week_number
            WHERE w.campaign_id = campaign_uuid
            ORDER BY w.week_number
        )
    ) INTO result
    FROM campaigns c
    WHERE c.id = campaign_uuid;
    
    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_12_week_plan_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_12_week_plan_overview(campaign_uuid uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'campaign_id', c.id,
        'campaign_name', c.name,
        'start_date', c.start_date,
        'end_date', c.end_date,
        'weeks', (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'week_number', cp.week_number,
                    'theme', cp.theme,
                    'focus_area', cp.focus_area,
                    'alignment_status', cp.alignment_status,
                    'content_count', COUNT(cp.id),
                    'published_count', COUNT(CASE WHEN cp.status = 'published' THEN 1 END),
                    'platforms', array_agg(DISTINCT cp.platform),
                    'content_types', array_agg(DISTINCT cp.content_type)
                )
            )
            FROM content_plans cp
            WHERE cp.campaign_id = campaign_uuid AND cp.week_number IS NOT NULL
            GROUP BY cp.week_number, cp.theme, cp.focus_area, cp.alignment_status
            ORDER BY cp.week_number
        )
    ) INTO result
    FROM campaigns c
    WHERE c.id = campaign_uuid;
    
    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_campaign_progress(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_campaign_progress(campaign_uuid uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'campaign_id', c.id,
        'name', c.name,
        'status', c.status,
        'current_stage', c.current_stage,
        'goals_count', COUNT(cg.id),
        'content_plans_count', COUNT(cp.id),
        'published_content', COUNT(CASE WHEN cp.status = 'published' THEN 1 END),
        'ai_feedback_count', COUNT(af.id),
        'improvements_count', COUNT(ai.id)
    ) INTO result
    FROM campaigns c
    LEFT JOIN campaign_goals cg ON c.id = cg.campaign_id
    LEFT JOIN content_plans cp ON c.id = cp.campaign_id
    LEFT JOIN ai_feedback af ON c.id = af.campaign_id
    LEFT JOIN ai_improvements ai ON c.id = ai.campaign_id
    WHERE c.id = campaign_uuid
    GROUP BY c.id, c.name, c.status, c.current_stage;
    
    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_day_detail_view(uuid, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_day_detail_view(campaign_uuid uuid, week_num integer, day_name character varying) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    result JSONB;
    content_item JSONB;
BEGIN
    SELECT jsonb_build_object(
        'campaign_id', c.id,
        'campaign_name', c.name,
        'week_number', week_num,
        'day_of_week', day_name,
        'date', dcp.date,
        'theme', wcr.theme,
        'focus_area', wcr.focus_area,
        'content_items', (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', dcp.id,
                    'platform', dcp.platform,
                    'content_type', dcp.content_type,
                    'title', dcp.title,
                    'content', dcp.content,
                    'hashtags', dcp.hashtags,
                    'mentions', dcp.mentions,
                    'scheduled_time', dcp.scheduled_time,
                    'status', dcp.status,
                    'priority', dcp.priority,
                    'media_urls', dcp.media_urls,
                    'required_resources', dcp.required_resources,
                    'posting_strategy', dcp.posting_strategy,
                    'expected_engagement', dcp.expected_engagement,
                    'target_audience', dcp.target_audience,
                    'ai_generated', dcp.ai_generated,
                    'created_at', dcp.created_at,
                    'updated_at', dcp.updated_at
                )
            )
            FROM daily_content_plans dcp
            WHERE dcp.campaign_id = campaign_uuid 
            AND dcp.week_number = week_num 
            AND dcp.day_of_week = day_name
            ORDER BY dcp.scheduled_time, dcp.created_at
        ),
        'total_items', (
            SELECT COUNT(*) FROM daily_content_plans 
            WHERE campaign_id = campaign_uuid 
            AND week_number = week_num 
            AND day_of_week = day_name
        ),
        'status_summary', (
            SELECT jsonb_build_object(
                'planned', COUNT(CASE WHEN status = 'planned' THEN 1 END),
                'content_created', COUNT(CASE WHEN status = 'content-created' THEN 1 END),
                'media_ready', COUNT(CASE WHEN status = 'media-ready' THEN 1 END),
                'scheduled', COUNT(CASE WHEN status = 'scheduled' THEN 1 END),
                'published', COUNT(CASE WHEN status = 'published' THEN 1 END)
            )
            FROM daily_content_plans 
            WHERE campaign_id = campaign_uuid 
            AND week_number = week_num 
            AND day_of_week = day_name
        ),
        'platforms', (
            SELECT array_agg(DISTINCT platform) 
            FROM daily_content_plans 
            WHERE campaign_id = campaign_uuid 
            AND week_number = week_num 
            AND day_of_week = day_name
        ),
        'content_types', (
            SELECT array_agg(DISTINCT content_type) 
            FROM daily_content_plans 
            WHERE campaign_id = campaign_uuid 
            AND week_number = week_num 
            AND day_of_week = day_name
        )
    ) INTO result
    FROM campaigns c
    LEFT JOIN weekly_content_refinements wcr ON c.id = wcr.campaign_id AND wcr.week_number = week_num
    LEFT JOIN daily_content_plans dcp ON c.id = dcp.campaign_id AND dcp.week_number = week_num AND dcp.day_of_week = day_name
    WHERE c.id = campaign_uuid
    LIMIT 1;
    
    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_engagement_thread_message_distance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_engagement_thread_message_distance(p_thread_id uuid, p_last_processed_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF p_last_processed_id IS NULL THEN
    RETURN (SELECT COUNT(*)::INTEGER FROM engagement_messages WHERE thread_id = p_thread_id);
  END IF;
  RETURN (
    SELECT COUNT(*)::INTEGER
    FROM engagement_messages em
    WHERE em.thread_id = p_thread_id
    AND (em.platform_created_at, em.id) > (
      SELECT e.platform_created_at, e.id FROM engagement_messages e
      WHERE e.id = p_last_processed_id AND e.thread_id = p_thread_id
    )
  );
END;
$$;


--
-- Name: get_engagement_thread_message_distance(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_engagement_thread_message_distance(p_thread_id uuid, p_last_processed_id uuid, p_threshold integer DEFAULT 5) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  row_count INTEGER;
BEGIN
  IF p_last_processed_id IS NULL THEN
    SELECT COUNT(*) INTO row_count FROM (
      SELECT 1 FROM engagement_messages WHERE thread_id = p_thread_id
      ORDER BY platform_created_at, id
      LIMIT p_threshold
    ) t;
    RETURN row_count >= p_threshold;
  END IF;

  SELECT COUNT(*) INTO row_count FROM (
    SELECT 1 FROM engagement_messages em
    WHERE em.thread_id = p_thread_id
    AND (em.platform_created_at, em.id) > (
      SELECT e.platform_created_at, e.id FROM engagement_messages e
      WHERE e.id = p_last_processed_id AND e.thread_id = p_thread_id
    )
    ORDER BY em.platform_created_at, em.id
    LIMIT p_threshold
  ) t;
  RETURN row_count >= p_threshold;
END;
$$;


--
-- Name: get_lead_recompute_queue_approx_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_lead_recompute_queue_approx_count() RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT COALESCE((SELECT c.reltuples::bigint FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relname = 'lead_thread_recompute_queue' AND n.nspname = 'public'), 0);
$$;


--
-- Name: get_usage_report(uuid, uuid, text, text, text, text, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_usage_report(p_organization_id uuid, p_campaign_id uuid DEFAULT NULL::uuid, p_process_type text DEFAULT NULL::text, p_source_type text DEFAULT NULL::text, p_provider_name text DEFAULT NULL::text, p_model_name text DEFAULT NULL::text, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_include_detail boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  base_where text := ' organization_id = $1 ';
  params jsonb;
  rec record;
  totals jsonb;
  by_provider_model jsonb := '[]'::jsonb;
  by_process jsonb := '[]'::jsonb;
  by_campaign jsonb := '[]'::jsonb;
  recent_events jsonb := '[]'::jsonb;
  total_events bigint;
  total_input bigint;
  total_output bigint;
  total_tokens bigint;
  total_cost numeric;
  avg_latency numeric;
  error_count bigint;
  detail_limit int := 100;
begin
  -- Build base filter (organization_id only here; extra filters in subqueries)
  -- Totals
  select
    count(*)::bigint,
    coalesce(sum(input_tokens), 0)::bigint,
    coalesce(sum(output_tokens), 0)::bigint,
    coalesce(sum(total_tokens), 0)::bigint,
    coalesce(sum(total_cost), 0),
    coalesce(avg(latency_ms), 0),
    count(*) filter (where error_flag = true)::bigint
  into total_events, total_input, total_output, total_tokens, total_cost, avg_latency, error_count
  from usage_events
  where organization_id = p_organization_id
    and (p_campaign_id is null or campaign_id = p_campaign_id)
    and (p_process_type is null or process_type = p_process_type)
    and (p_source_type is null or source_type = p_source_type)
    and (p_provider_name is null or provider_name = p_provider_name)
    and (p_model_name is null or model_name = p_model_name)
    and (p_start_date is null or created_at >= p_start_date)
    and (p_end_date is null or created_at <= p_end_date);

  totals := jsonb_build_object(
    'total_events', coalesce(total_events, 0),
    'total_input_tokens', coalesce(total_input, 0),
    'total_output_tokens', coalesce(total_output, 0),
    'total_tokens', coalesce(total_tokens, 0),
    'total_cost', coalesce(total_cost, 0),
    'avg_latency_ms', round(coalesce(avg_latency, 0)::numeric, 2),
    'error_rate_percent', case when coalesce(total_events, 0) = 0 then 0
      else round((coalesce(error_count, 0)::numeric / total_events::numeric * 100)::numeric, 2) end
  );

  -- By provider + model
  select coalesce(jsonb_agg(sub), '[]'::jsonb) into by_provider_model
  from (
    select jsonb_build_object(
      'provider_name', provider_name,
      'model_name', model_name,
      'total_tokens', coalesce(sum(total_tokens), 0)::bigint,
      'total_cost', coalesce(sum(total_cost), 0),
      'avg_latency_ms', round(coalesce(avg(latency_ms), 0)::numeric, 2),
      'error_rate_percent', case when count(*) = 0 then 0
        else round((count(*) filter (where error_flag = true)::numeric / count(*)::numeric * 100)::numeric, 2) end
    ) as sub
    from usage_events
    where organization_id = p_organization_id
      and (p_campaign_id is null or campaign_id = p_campaign_id)
      and (p_process_type is null or process_type = p_process_type)
      and (p_source_type is null or source_type = p_source_type)
      and (p_provider_name is null or provider_name = p_provider_name)
      and (p_model_name is null or model_name = p_model_name)
      and (p_start_date is null or created_at >= p_start_date)
      and (p_end_date is null or created_at <= p_end_date)
    group by provider_name, model_name
  ) x;

  -- By process_type
  select coalesce(jsonb_agg(sub), '[]'::jsonb) into by_process
  from (
    select jsonb_build_object(
      'process_type', process_type,
      'total_events', count(*)::bigint,
      'total_tokens', coalesce(sum(total_tokens), 0)::bigint,
      'total_cost', coalesce(sum(total_cost), 0),
      'avg_latency_ms', round(coalesce(avg(latency_ms), 0)::numeric, 2)
    ) as sub
    from usage_events
    where organization_id = p_organization_id
      and (p_campaign_id is null or campaign_id = p_campaign_id)
      and (p_process_type is null or process_type = p_process_type)
      and (p_source_type is null or source_type = p_source_type)
      and (p_provider_name is null or provider_name = p_provider_name)
      and (p_model_name is null or model_name = p_model_name)
      and (p_start_date is null or created_at >= p_start_date)
      and (p_end_date is null or created_at <= p_end_date)
    group by process_type
  ) x;

  -- By campaign_id
  select coalesce(jsonb_agg(sub), '[]'::jsonb) into by_campaign
  from (
    select jsonb_build_object(
      'campaign_id', campaign_id,
      'total_events', count(*)::bigint,
      'total_tokens', coalesce(sum(total_tokens), 0)::bigint,
      'total_cost', coalesce(sum(total_cost), 0),
      'avg_latency_ms', round(coalesce(avg(latency_ms), 0)::numeric, 2)
    ) as sub
    from usage_events
    where organization_id = p_organization_id
      and campaign_id is not null
      and (p_campaign_id is null or campaign_id = p_campaign_id)
      and (p_process_type is null or process_type = p_process_type)
      and (p_source_type is null or source_type = p_source_type)
      and (p_provider_name is null or provider_name = p_provider_name)
      and (p_model_name is null or model_name = p_model_name)
      and (p_start_date is null or created_at >= p_start_date)
      and (p_end_date is null or created_at <= p_end_date)
    group by campaign_id
  ) x;

  -- Recent events (last 100, for detail=true)
  if p_include_detail then
    select coalesce(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb) into recent_events
    from (
      select id, organization_id, campaign_id, user_id, source_type, provider_name, model_name,
             source_name, process_type, input_tokens, output_tokens, total_tokens,
             latency_ms, error_flag, error_type, unit_cost, total_cost, pricing_snapshot,
             metadata, created_at
      from usage_events
      where organization_id = p_organization_id
        and (p_campaign_id is null or campaign_id = p_campaign_id)
        and (p_process_type is null or process_type = p_process_type)
        and (p_source_type is null or source_type = p_source_type)
        and (p_provider_name is null or provider_name = p_provider_name)
        and (p_model_name is null or model_name = p_model_name)
        and (p_start_date is null or created_at >= p_start_date)
        and (p_end_date is null or created_at <= p_end_date)
      order by created_at desc
      limit detail_limit
    ) t;
  end if;

  return jsonb_build_object(
    'totals', totals,
    'by_provider_model', by_provider_model,
    'by_process', by_process,
    'by_campaign', by_campaign,
    'recent_events', recent_events
  );
end;
$_$;


--
-- Name: get_week_detail_view(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_week_detail_view(campaign_uuid uuid, week_num integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    result JSONB;
    day_data JSONB;
BEGIN
    SELECT jsonb_build_object(
        'campaign_id', c.id,
        'campaign_name', c.name,
        'week_number', week_num,
        'theme', wcr.theme,
        'focus_area', wcr.focus_area,
        'refinement_status', wcr.refinement_status,
        'ai_enhanced', wcr.ai_enhancement_applied,
        'manually_edited', wcr.manual_edits_applied,
        'finalized', wcr.finalized,
        'daily_populated', wcr.daily_plan_populated,
        'week_start_date', c.start_date + INTERVAL '1 week' * (week_num - 1),
        'week_end_date', c.start_date + INTERVAL '1 week' * (week_num - 1) + INTERVAL '6 days',
        'days', (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'day_of_week', dcp.day_of_week,
                    'date', dcp.date,
                    'content_count', COUNT(dcp.id),
                    'platforms', array_agg(DISTINCT dcp.platform),
                    'content_types', array_agg(DISTINCT dcp.content_type),
                    'status_summary', jsonb_build_object(
                        'planned', COUNT(CASE WHEN dcp.status = 'planned' THEN 1 END),
                        'content_created', COUNT(CASE WHEN dcp.status = 'content-created' THEN 1 END),
                        'media_ready', COUNT(CASE WHEN dcp.status = 'media-ready' THEN 1 END),
                        'scheduled', COUNT(CASE WHEN dcp.status = 'scheduled' THEN 1 END),
                        'published', COUNT(CASE WHEN dcp.status = 'published' THEN 1 END)
                    )
                )
            )
            FROM daily_content_plans dcp
            WHERE dcp.campaign_id = campaign_uuid AND dcp.week_number = week_num
            GROUP BY dcp.day_of_week, dcp.date
            ORDER BY dcp.date
        ),
        'total_content_items', (
            SELECT COUNT(*) FROM content_plans 
            WHERE campaign_id = campaign_uuid AND week_number = week_num
        ),
        'total_daily_plans', (
            SELECT COUNT(*) FROM daily_content_plans 
            WHERE campaign_id = campaign_uuid AND week_number = week_num
        )
    ) INTO result
    FROM campaigns c
    LEFT JOIN weekly_content_refinements wcr ON c.id = wcr.campaign_id AND wcr.week_number = week_num
    WHERE c.id = campaign_uuid;
    
    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: guard_approval_post_execute(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_approval_post_execute() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.executed_at IS NOT NULL THEN
    RAISE EXCEPTION 'APPROVAL_FROZEN: approval % is executed and immutable', OLD.id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_bo_no_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_bo_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'BILLING_OP_NO_DELETE: row % is operational history and cannot be deleted', OLD.id
    USING ERRCODE = 'P0001';
END;
$$;


--
-- Name: guard_contract_immutable_after_active(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_contract_immutable_after_active() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status IN ('active', 'expired', 'terminated', 'renewed') THEN
    IF NEW.signed_by_virality IS DISTINCT FROM OLD.signed_by_virality
       OR NEW.signed_by_org_name IS DISTINCT FROM OLD.signed_by_org_name
       OR NEW.total_contract_value IS DISTINCT FROM OLD.total_contract_value
       OR NEW.signed_contract_url IS DISTINCT FROM OLD.signed_contract_url
       OR NEW.start_date IS DISTINCT FROM OLD.start_date
       OR NEW.end_date   IS DISTINCT FROM OLD.end_date THEN
      RAISE EXCEPTION 'CONTRACT_FROZEN: signed-and-active contract % is immutable on financial fields', OLD.id
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_firebase_uid_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_firebase_uid_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
  BEGIN
    IF OLD.firebase_uid IS NOT NULL
       AND NEW.firebase_uid IS DISTINCT FROM OLD.firebase_uid
    THEN
      RAISE EXCEPTION 'firebase_uid cannot be changed once set (user_id=%, existing=%, attempted=%)',
        OLD.id, OLD.firebase_uid, NEW.firebase_uid
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END;
  $$;


--
-- Name: guard_invoice_line_items_frozen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_invoice_line_items_frozen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status text;
BEGIN
  SELECT status INTO v_status FROM public.invoices WHERE id = COALESCE(NEW.invoice_id, OLD.invoice_id);
  IF v_status IS NOT NULL AND v_status <> 'draft' THEN
    RAISE EXCEPTION 'INVOICE_LINE_ITEM_FROZEN: invoice status=% prevents line-item % on row %',
      v_status, TG_OP, COALESCE(OLD.id, NEW.id)
      USING ERRCODE = 'P0001';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: guard_jer_status_monotonic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_jer_status_monotonic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_terminal_old boolean;
  v_terminal_new boolean;
BEGIN
  v_terminal_old := OLD.status IN ('completed', 'released', 'orphan_reaped', 'duplicate_blocked');
  v_terminal_new := NEW.status IN ('completed', 'released', 'orphan_reaped', 'duplicate_blocked');
  IF v_terminal_old AND NEW.status <> OLD.status THEN
    RAISE EXCEPTION 'JER_STATUS_FROZEN: % is terminal, cannot transition to %', OLD.status, NEW.status
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_render_queue_monotonic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_render_queue_monotonic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_terminal CONSTANT text[] := ARRAY['completed','cancelled'];
BEGIN
  IF OLD.queue_state = ANY (v_terminal) AND NEW.queue_state <> OLD.queue_state THEN
    RAISE EXCEPTION
      'RENDER_QUEUE_FROZEN: % is terminal, cannot transition to % (queue_job=%)',
      OLD.queue_state, NEW.queue_state, OLD.id USING ERRCODE = 'P0001';
  END IF;
  IF NEW.retry_count < OLD.retry_count THEN
    RAISE EXCEPTION 'RENDER_QUEUE_RETRY_MONOTONIC: retry_count cannot decrease (% -> %)',
      OLD.retry_count, NEW.retry_count USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_render_state_monotonic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_render_state_monotonic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_terminal CONSTANT text[] := ARRAY[
    'scheduling_ready','handed_to_human',
    'failed_render','failed_moderation_pre','failed_moderation_post',
    'failed_provider_exhausted','failed_timeout',
    'cancelled_by_user','cancelled_superseded','cancelled_quota'
  ];
BEGIN
  IF OLD.current_state = ANY (v_terminal) AND NEW.current_state <> OLD.current_state THEN
    RAISE EXCEPTION
      'RENDER_STATE_FROZEN: % is terminal, cannot transition to % (job=%)',
      OLD.current_state, NEW.current_state, OLD.render_job_id
      USING ERRCODE = 'P0001';
  END IF;
  -- retry_count is monotonic non-decreasing.
  IF NEW.retry_count < OLD.retry_count THEN
    RAISE EXCEPTION 'RENDER_RETRY_MONOTONIC: retry_count cannot decrease (% -> %)',
      OLD.retry_count, NEW.retry_count USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: image_metadata_append_query(text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.image_metadata_append_query(p_provider_ids text[], p_query text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.image_metadata
  SET search_queries = array_append(search_queries, p_query)
  WHERE provider_id = ANY(p_provider_ids)
    AND NOT (search_queries @> ARRAY[p_query]);
END;
$$;


--
-- Name: increment_automation_usage_if_allowed(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_automation_usage_if_allowed(p_org_id uuid, p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_day         date := (NOW() AT TIME ZONE 'UTC')::date;
  v_new_count   integer;
BEGIN
  INSERT INTO public.automation_usage (organization_id, day, actions_executed, updated_at)
  VALUES (p_org_id, v_day, 1, NOW())
  ON CONFLICT (organization_id, day)
  DO UPDATE SET
    actions_executed = public.automation_usage.actions_executed + 1,
    updated_at       = NOW()
  WHERE  public.automation_usage.actions_executed < p_limit
  RETURNING actions_executed INTO v_new_count;

  RETURN v_new_count;
END;
$$;


--
-- Name: increment_bolt_run_progress(uuid, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_bolt_run_progress(p_run_id uuid, p_scheduled integer DEFAULT 0, p_skipped integer DEFAULT 0, p_job_done integer DEFAULT 1, p_job_failed integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  UPDATE bolt_execution_runs
  SET
    content_jobs_done  = content_jobs_done  + p_job_done,
    content_jobs_failed = content_jobs_failed + p_job_failed,
    posts_scheduled    = posts_scheduled    + p_scheduled,
    posts_skipped      = posts_skipped      + p_skipped,
    updated_at         = now()
  WHERE id = p_run_id;
END;
$$;


--
-- Name: increment_response_perf_followup(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_response_perf_followup(p_thread_id uuid, p_new_message_platform_created_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  UPDATE response_performance_metrics
  SET engagement_reply_count = engagement_reply_count + 1
  WHERE id = (
    SELECT id FROM response_performance_metrics
    WHERE thread_id = p_thread_id
    AND created_at < p_new_message_platform_created_at
    AND evaluation_window_closed = false
    ORDER BY created_at DESC
    LIMIT 1
  );
END;
$$;


--
-- Name: increment_response_perf_like(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_response_perf_like(p_liked_message_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_parent_id UUID;
BEGIN
  SELECT parent_message_id INTO v_parent_id
  FROM engagement_messages WHERE id = p_liked_message_id;
  IF v_parent_id IS NULL THEN RETURN; END IF;

  UPDATE response_performance_metrics
  SET engagement_like_count = engagement_like_count + 1
  WHERE id = (
    SELECT id FROM response_performance_metrics
    WHERE message_id = v_parent_id
    ORDER BY created_at DESC
    LIMIT 1
  );
END;
$$;


--
-- Name: increment_template_usage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_template_usage(template_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    UPDATE content_templates
    SET usage_count = usage_count + 1,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = template_id;
END;
$$;


--
-- Name: increment_usage_meter(uuid, integer, integer, bigint, bigint, bigint, bigint, bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_usage_meter(p_organization_id uuid, p_year integer, p_month integer, p_llm_input_tokens bigint DEFAULT 0, p_llm_output_tokens bigint DEFAULT 0, p_llm_total_tokens bigint DEFAULT 0, p_external_api_calls bigint DEFAULT 0, p_automation_executions bigint DEFAULT 0, p_total_cost numeric DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into usage_meter_monthly (
    organization_id, year, month,
    llm_input_tokens, llm_output_tokens, llm_total_tokens,
    external_api_calls, automation_executions, total_cost,
    created_at, updated_at
  )
  values (
    p_organization_id, p_year, p_month,
    coalesce(p_llm_input_tokens, 0), coalesce(p_llm_output_tokens, 0), coalesce(p_llm_total_tokens, 0),
    coalesce(p_external_api_calls, 0), coalesce(p_automation_executions, 0), coalesce(p_total_cost, 0),
    now(), now()
  )
  on conflict (organization_id, year, month)
  do update set
    llm_input_tokens = usage_meter_monthly.llm_input_tokens + coalesce(EXCLUDED.llm_input_tokens, 0),
    llm_output_tokens = usage_meter_monthly.llm_output_tokens + coalesce(EXCLUDED.llm_output_tokens, 0),
    llm_total_tokens = usage_meter_monthly.llm_total_tokens + coalesce(EXCLUDED.llm_total_tokens, 0),
    external_api_calls = usage_meter_monthly.external_api_calls + coalesce(EXCLUDED.external_api_calls, 0),
    automation_executions = usage_meter_monthly.automation_executions + coalesce(EXCLUDED.automation_executions, 0),
    total_cost = usage_meter_monthly.total_cost + coalesce(EXCLUDED.total_cost, 0),
    updated_at = now();
end;
$$;


--
-- Name: insert_engagement_signals_avoid_dupes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_engagement_signals_avoid_dupes(signals jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  r record;
  inserted integer := 0;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset(signals) AS x(
    campaign_id uuid,
    activity_id text,
    platform text,
    source_type text,
    source_id text,
    conversation_url text,
    author text,
    content text,
    signal_type text,
    engagement_score numeric,
    organization_id uuid
  )
  LOOP
    INSERT INTO campaign_activity_engagement_signals (
      campaign_id, activity_id, platform, source_type, source_id,
      conversation_url, author, content, signal_type, engagement_score, organization_id
    ) VALUES (
      r.campaign_id, r.activity_id, r.platform, r.source_type, r.source_id,
      r.conversation_url, r.author, r.content, r.signal_type, r.engagement_score, r.organization_id
    )
    ON CONFLICT (platform, source_id) DO NOTHING;
    inserted := inserted + 1;
  END LOOP;
  RETURN inserted;
END;
$$;


--
-- Name: insert_thread_atomic(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_thread_atomic(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_root_id            uuid := gen_random_uuid();
  v_node_ids           uuid[] := ARRAY[v_root_id];
  v_user_id            uuid := (p_payload->>'user_id')::uuid;
  v_social_account_id  uuid := NULLIF(p_payload->>'social_account_id', '')::uuid;
  v_campaign_id        uuid := NULLIF(p_payload->>'campaign_id', '')::uuid;
  v_platform           text := p_payload->>'platform';
  v_scheduled_for      timestamptz := (p_payload->>'scheduled_for')::timestamptz;
  v_title              text := NULLIF(p_payload->>'title', '');
  v_hashtags           text[] := ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_payload->'hashtags', '[]'::jsonb)));
  v_nodes              jsonb := p_payload->'nodes';
  v_content_type       text := CASE WHEN v_platform = 'twitter' THEN 'thread' ELSE 'post' END;
  v_root_status        text := COALESCE(NULLIF(p_payload->>'root_status', ''), 'scheduled');
  v_thread_title       text;
  v_idx                int;
  v_node               jsonb;
  v_child_id           uuid;
  v_hashtag_arg        text[] := CASE WHEN array_length(v_hashtags, 1) > 0 THEN v_hashtags ELSE NULL END;
  -- G6/G2 — per-node media extraction helpers.
  v_node_media_urls    text[];
  v_node_media_types   text[];
  -- Root row also accepts per-node media via nodes[0] (the root is position 0).
  v_root_media_urls    text[];
  v_root_media_types   text[];
BEGIN
  IF v_nodes IS NULL OR jsonb_typeof(v_nodes) <> 'array' OR jsonb_array_length(v_nodes) < 2 THEN
    RAISE EXCEPTION 'thread_must_have_at_least_two_nodes';
  END IF;

  IF v_root_status <> 'scheduled' AND v_root_status <> 'draft' THEN
    RAISE EXCEPTION 'thread_invalid_root_status';
  END IF;

  v_thread_title := COALESCE(v_title, LEFT(v_nodes->0->>'content', 200));

  -- G6/G2 — extract per-node media for the root (nodes[0]). Absent or empty
  -- arrays produce NULL (column default), preserving pre-G6 behavior.
  v_root_media_urls := ARRAY(
    SELECT jsonb_array_elements_text(COALESCE(v_nodes->0->'media_urls', '[]'::jsonb))
  );
  v_root_media_types := ARRAY(
    SELECT jsonb_array_elements_text(COALESCE(v_nodes->0->'media_types', '[]'::jsonb))
  );

  INSERT INTO scheduled_posts (
    id, user_id, social_account_id, campaign_id,
    platform, content_type, content, title, hashtags,
    media_urls, media_types,
    scheduled_for, status,
    parent_post_id, thread_position, is_thread_start, thread_title,
    created_at, updated_at
  ) VALUES (
    v_root_id, v_user_id, v_social_account_id, v_campaign_id,
    v_platform, v_content_type, v_nodes->0->>'content', v_title, v_hashtag_arg,
    CASE WHEN array_length(v_root_media_urls, 1) > 0 THEN v_root_media_urls ELSE NULL END,
    CASE WHEN array_length(v_root_media_types, 1) > 0 THEN v_root_media_types ELSE NULL END,
    v_scheduled_for, v_root_status,
    NULL, 0, TRUE, v_thread_title,
    now(), now()
  );

  -- Child rows: status='draft' so the legacy publisher cron ignores them.
  -- G6/G2 — per-node media_urls + media_types are extracted from each child's
  -- JSONB entry and inserted into the row's columns. The orchestrator's
  -- per-row platform call (publishToPlatform) already reads media_urls from
  -- the row's own column, so this is the only change required for per-node
  -- propagation.
  FOR v_idx IN 1 .. jsonb_array_length(v_nodes) - 1 LOOP
    v_node := v_nodes->v_idx;
    v_child_id := gen_random_uuid();
    v_node_media_urls := ARRAY(
      SELECT jsonb_array_elements_text(COALESCE(v_node->'media_urls', '[]'::jsonb))
    );
    v_node_media_types := ARRAY(
      SELECT jsonb_array_elements_text(COALESCE(v_node->'media_types', '[]'::jsonb))
    );
    INSERT INTO scheduled_posts (
      id, user_id, social_account_id, campaign_id,
      platform, content_type, content,
      media_urls, media_types,
      scheduled_for, status,
      parent_post_id, thread_position, is_thread_start,
      created_at, updated_at
    ) VALUES (
      v_child_id, v_user_id, v_social_account_id, v_campaign_id,
      v_platform, v_content_type, v_node->>'content',
      CASE WHEN array_length(v_node_media_urls, 1) > 0 THEN v_node_media_urls ELSE NULL END,
      CASE WHEN array_length(v_node_media_types, 1) > 0 THEN v_node_media_types ELSE NULL END,
      v_scheduled_for, 'draft',
      v_root_id, (v_node->>'position')::int, FALSE,
      now(), now()
    );
    v_node_ids := array_append(v_node_ids, v_child_id);
  END LOOP;

  RETURN jsonb_build_object(
    'root_id',  v_root_id,
    'node_ids', to_jsonb(v_node_ids)
  );
END;
$$;


--
-- Name: invalidate_user_sessions(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_user_sessions(p_user_id uuid, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_now      TIMESTAMPTZ := NOW();
  v_revoked  INTEGER;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'INVALIDATE_USER_SESSIONS_NULL_USER_ID';
  END IF;
  IF p_reason IS NULL OR LENGTH(TRIM(p_reason)) = 0 THEN
    RAISE EXCEPTION 'INVALIDATE_USER_SESSIONS_MISSING_REASON';
  END IF;

  UPDATE users
    SET session_revoked_after = v_now,
        updated_at = v_now
    WHERE id = p_user_id;

  WITH revoked AS (
    UPDATE auth_sessions
      SET revoked_at = v_now,
          revocation_reason = p_reason
      WHERE user_id = p_user_id
        AND revoked_at IS NULL
      RETURNING id
  )
  SELECT COUNT(*) INTO v_revoked FROM revoked;

  RETURN v_revoked;
END;
$$;


--
-- Name: is_valid_creator_daily_content_payload(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_valid_creator_daily_content_payload(p_intent_type text, p_asset_type text, p_content text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  parsed JSONB;
BEGIN
  IF COALESCE(p_intent_type, '') <> 'creator' THEN
    RETURN TRUE;
  END IF;

  BEGIN
    parsed := p_content::jsonb;
  EXCEPTION WHEN others THEN
    RETURN FALSE;
  END;

  IF parsed IS NULL THEN
    RETURN FALSE;
  END IF;
  IF NOT (parsed ? 'intent_type' AND parsed ? 'asset_type' AND parsed ? 'asset_payload' AND parsed ? 'packaging') THEN
    RETURN FALSE;
  END IF;
  IF parsed->>'intent_type' <> 'creator' THEN
    RETURN FALSE;
  END IF;
  IF COALESCE(p_asset_type, '') <> '' AND parsed->>'asset_type' <> p_asset_type THEN
    RETURN FALSE;
  END IF;
  IF jsonb_typeof(parsed->'packaging') <> 'object' THEN
    RETURN FALSE;
  END IF;
  IF jsonb_typeof(parsed->'asset_instruction') <> 'object' THEN
    RETURN FALSE;
  END IF;
  IF jsonb_typeof(parsed->'asset_payload') <> 'object' THEN
    RETURN FALSE;
  END IF;
  IF NOT (
    (parsed->'packaging' ? 'caption')
    AND (parsed->'packaging' ? 'hashtags')
    AND (parsed->'packaging' ? 'meta_description')
    AND (parsed->'packaging' ? 'keywords')
    AND (parsed->'packaging' ? 'cta')
  ) THEN
    RETURN FALSE;
  END IF;
  IF jsonb_typeof(parsed->'packaging'->'hashtags') <> 'array' THEN
    RETURN FALSE;
  END IF;
  IF jsonb_typeof(parsed->'packaging'->'keywords') <> 'array' THEN
    RETURN FALSE;
  END IF;
  IF p_asset_type = 'carousel' THEN
    IF NOT (parsed->'asset_payload' ? 'slides') OR jsonb_typeof(parsed->'asset_payload'->'slides') <> 'array' THEN
      RETURN FALSE;
    END IF;
  ELSIF p_asset_type = 'image' THEN
    IF NOT (parsed->'asset_payload' ? 'visual_descriptor') OR jsonb_typeof(parsed->'asset_payload'->'visual_descriptor') <> 'object' THEN
      RETURN FALSE;
    END IF;
  ELSIF p_asset_type = 'video' THEN
    IF NOT (parsed->'asset_payload' ? 'scenes') OR jsonb_typeof(parsed->'asset_payload'->'scenes') <> 'array' THEN
      RETURN FALSE;
    END IF;
  ELSIF p_asset_type IN ('post_with_asset', 'thread_with_asset') THEN
    IF NOT (parsed->'asset_payload' ? 'caption_blueprint') OR jsonb_typeof(parsed->'asset_payload'->'caption_blueprint') <> 'object' THEN
      RETURN FALSE;
    END IF;
  END IF;
  RETURN TRUE;
END;
$$;


--
-- Name: is_valid_creator_platform_asset_combo(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_valid_creator_platform_asset_combo(p_intent_type text, p_platform text, p_asset_type text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  normalized_platform TEXT := lower(trim(coalesce(p_platform, '')));
BEGIN
  IF coalesce(p_intent_type, '') <> 'creator' THEN
    RETURN TRUE;
  END IF;
  IF normalized_platform = 'twitter' THEN
    normalized_platform := 'x';
  END IF;

  IF normalized_platform = 'linkedin' THEN
    RETURN p_asset_type IN ('image', 'carousel', 'video', 'post_with_asset');
  ELSIF normalized_platform = 'instagram' THEN
    RETURN p_asset_type IN ('image', 'carousel', 'video', 'post_with_asset');
  ELSIF normalized_platform = 'facebook' THEN
    RETURN p_asset_type IN ('image', 'carousel', 'video', 'post_with_asset');
  ELSIF normalized_platform = 'threads' THEN
    RETURN p_asset_type IN ('image', 'video', 'post_with_asset');
  ELSIF normalized_platform = 'x' THEN
    RETURN p_asset_type IN ('image', 'video', 'thread_with_asset', 'post_with_asset');
  ELSIF normalized_platform = 'tiktok' THEN
    RETURN p_asset_type IN ('video');
  ELSIF normalized_platform = 'pinterest' THEN
    RETURN p_asset_type IN ('image', 'carousel', 'post_with_asset');
  ELSIF normalized_platform = 'youtube' THEN
    RETURN p_asset_type IN ('video', 'post_with_asset');
  END IF;
  RETURN FALSE;
END;
$$;


--
-- Name: lead_platform_increment_converted(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_platform_increment_converted(p_company_id uuid, p_platform text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  insert into lead_platform_stats_v1 (company_id, platform, total_signals, total_converted, conversion_rate)
  values (p_company_id, p_platform, 1, 1, 1.0)
  on conflict (company_id, platform) do update set
    total_converted = lead_platform_stats_v1.total_converted + 1,
    conversion_rate = (lead_platform_stats_v1.total_converted + 1)::numeric / nullif(lead_platform_stats_v1.total_signals, 0),
    last_updated = now();
end;
$$;


--
-- Name: lead_platform_increment_signals(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_platform_increment_signals(p_company_id uuid, p_platform text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  insert into lead_platform_stats_v1 (company_id, platform, total_signals)
  values (p_company_id, p_platform, 1)
  on conflict (company_id, platform) do update set
    total_signals = lead_platform_stats_v1.total_signals + 1,
    last_updated = now();
end;
$$;


--
-- Name: lookup_fx_rate(text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_fx_rate(p_source text, p_target text, p_as_of timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_row public.currency_exchange_rates%ROWTYPE;
BEGIN
  IF upper(p_source) = upper(p_target) THEN
    RETURN jsonb_build_object('rate', 1.0, 'provider', 'identity', 'effective_at', p_as_of);
  END IF;

  SELECT * INTO v_row FROM public.currency_exchange_rates
   WHERE source_currency = upper(p_source)
     AND target_currency = upper(p_target)
     AND effective_at <= p_as_of
   ORDER BY effective_at DESC
   LIMIT 1;

  IF v_row.id IS NULL THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object(
    'id',             v_row.id,
    'rate',           v_row.rate,
    'provider',       v_row.provider,
    'snapshot_id',    v_row.snapshot_id,
    'effective_at',   v_row.effective_at
  );
END;
$$;


--
-- Name: match_clusters_by_embedding(extensions.vector, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_clusters_by_embedding(query_embedding extensions.vector, match_limit integer DEFAULT 5, since_ts timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(cluster_id uuid, cluster_topic text, topic_embedding extensions.vector, signal_count integer, last_updated timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT sc.cluster_id, sc.cluster_topic, sc.topic_embedding, sc.signal_count, sc.last_updated
  FROM signal_clusters sc
  WHERE sc.topic_embedding IS NOT NULL
    AND (since_ts IS NULL OR sc.last_updated >= since_ts)
  ORDER BY sc.topic_embedding <=> query_embedding
  LIMIT match_limit;
$$;


--
-- Name: merge_unified_persons(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_unified_persons(winner_id uuid, loser_id uuid, merge_reason text, actor text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  winner_company_id UUID;
BEGIN
  IF winner_id = loser_id THEN
    RAISE EXCEPTION 'merge_unified_persons: winner and loser cannot be the same id';
  END IF;

  SELECT company_id INTO winner_company_id
  FROM public.unified_persons WHERE id = winner_id;

  IF winner_company_id IS NULL THEN
    RAISE EXCEPTION 'merge_unified_persons: winner % not found', winner_id;
  END IF;

  -- Re-point all FK columns from loser to winner
  UPDATE public.users
     SET unified_person_id = winner_id WHERE unified_person_id = loser_id;
  UPDATE public.leads
     SET unified_person_id = winner_id WHERE unified_person_id = loser_id;
  UPDATE public.canonical_users
     SET unified_person_id = winner_id WHERE unified_person_id = loser_id;
  UPDATE public.canonical_leads
     SET unified_person_id = winner_id WHERE unified_person_id = loser_id;
  UPDATE public.canonical_revenue_events
     SET unified_person_id = winner_id WHERE unified_person_id = loser_id;
  UPDATE public.contacts
     SET unified_person_id = winner_id WHERE unified_person_id = loser_id;
  UPDATE public.engagement_threads
     SET unified_person_id = winner_id WHERE unified_person_id = loser_id;

  -- Audit row (actor stored in metadata since merged_by is UUID and actor is TEXT)
  INSERT INTO public.unified_person_merges (
    company_id, winner_person_id, loser_person_id, reason, metadata
  ) VALUES (
    winner_company_id,
    winner_id,
    loser_id,
    merge_reason,
    jsonb_build_object('actor', actor)
  );

  -- Delete the loser unified_persons row
  DELETE FROM public.unified_persons WHERE id = loser_id;
END;
$$;


--
-- Name: FUNCTION merge_unified_persons(winner_id uuid, loser_id uuid, merge_reason text, actor text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.merge_unified_persons(winner_id uuid, loser_id uuid, merge_reason text, actor text) IS 'Atomic merge of two unified_persons rows. Re-points FKs, writes audit, deletes loser.';


--
-- Name: meta_oauth_apply(jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meta_oauth_apply(p_connection jsonb, p_pages jsonb, p_instagrams jsonb, p_threads jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_connection_id    uuid;
  v_user_id          uuid := (p_connection->>'user_id')::uuid;
  v_company_id       uuid := (p_connection->>'company_id')::uuid;
  v_fb_user_id       text := p_connection->>'fb_user_id';
  v_idempotency_key  text := p_connection->>'idempotency_key';
  v_token_expires_at timestamptz := (p_connection->>'token_expires_at')::timestamptz;
  v_existing_id      uuid;
  v_existing_age     interval;
  v_page             jsonb;
  v_instagram        jsonb;
  v_thread           jsonb;
BEGIN
  IF v_user_id IS NULL OR v_company_id IS NULL OR v_fb_user_id IS NULL OR v_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'meta_oauth_apply: missing required connection fields';
  END IF;

  -- Idempotency short-circuit: if this exact code has been processed in the
  -- last hour, return the prior connection id without re-running side effects.
  SELECT id, now() - created_at
    INTO v_existing_id, v_existing_age
    FROM public.meta_oauth_connections
   WHERE idempotency_key = v_idempotency_key
   LIMIT 1;

  IF v_existing_id IS NOT NULL AND v_existing_age < interval '1 hour' THEN
    RETURN v_existing_id;
  END IF;

  -- Upsert parent connection (by company_id + fb_user_id).
  INSERT INTO public.meta_oauth_connections (
    user_id, company_id, fb_user_id,
    user_access_token, token_expires_at, granted_scopes,
    idempotency_key, last_refreshed_at, refresh_failed_at, refresh_error,
    created_at, updated_at
  )
  VALUES (
    v_user_id,
    v_company_id,
    v_fb_user_id,
    p_connection->>'user_access_token',
    v_token_expires_at,
    COALESCE(
      ARRAY(SELECT jsonb_array_elements_text(p_connection->'granted_scopes')),
      '{}'::text[]
    ),
    v_idempotency_key,
    now(),
    NULL,
    NULL,
    now(),
    now()
  )
  ON CONFLICT (company_id, fb_user_id) DO UPDATE
    SET user_access_token  = EXCLUDED.user_access_token,
        token_expires_at   = EXCLUDED.token_expires_at,
        granted_scopes     = EXCLUDED.granted_scopes,
        idempotency_key    = EXCLUDED.idempotency_key,
        last_refreshed_at  = now(),
        refresh_failed_at  = NULL,
        refresh_error      = NULL,
        updated_at         = now()
  RETURNING id INTO v_connection_id;

  -- Upsert facebook rows (one per Page).
  FOR v_page IN SELECT * FROM jsonb_array_elements(COALESCE(p_pages, '[]'::jsonb))
  LOOP
    INSERT INTO public.social_accounts (
      user_id, company_id, meta_connection_id,
      platform, platform_user_id,
      account_name, username,
      page_access_token, token_expires_at,
      is_active, is_system_user,
      last_sync_at, created_at, updated_at,
      access_token
    )
    VALUES (
      v_user_id, v_company_id, v_connection_id,
      'facebook',
      v_page->>'page_id',
      COALESCE(v_page->>'page_name', 'Facebook Page'),
      v_page->>'username',
      v_page->>'page_access_token',
      v_token_expires_at,
      true, false,
      now(), now(), now(),
      v_page->>'page_access_token'  -- legacy access_token column kept in sync
    )
    ON CONFLICT (company_id, platform, platform_user_id) DO UPDATE
      SET meta_connection_id = EXCLUDED.meta_connection_id,
          account_name       = EXCLUDED.account_name,
          username           = COALESCE(EXCLUDED.username, public.social_accounts.username),
          page_access_token  = EXCLUDED.page_access_token,
          access_token       = EXCLUDED.access_token,
          token_expires_at   = EXCLUDED.token_expires_at,
          is_active          = true,
          is_system_user     = false,
          last_sync_at       = now(),
          updated_at         = now();
  END LOOP;

  -- Upsert instagram rows.
  FOR v_instagram IN SELECT * FROM jsonb_array_elements(COALESCE(p_instagrams, '[]'::jsonb))
  LOOP
    INSERT INTO public.social_accounts (
      user_id, company_id, meta_connection_id,
      platform, platform_user_id,
      account_name, username,
      ig_user_token, token_expires_at,
      linked_page_id,
      is_active, is_system_user,
      last_sync_at, created_at, updated_at,
      access_token
    )
    VALUES (
      v_user_id, v_company_id, v_connection_id,
      'instagram',
      v_instagram->>'ig_business_id',
      COALESCE(v_instagram->>'name', '@' || COALESCE(v_instagram->>'username','instagram')),
      v_instagram->>'username',
      v_instagram->>'ig_user_token',
      v_token_expires_at,
      v_instagram->>'linked_page_id',
      true, false,
      now(), now(), now(),
      v_instagram->>'ig_user_token'
    )
    ON CONFLICT (company_id, platform, platform_user_id) DO UPDATE
      SET meta_connection_id = EXCLUDED.meta_connection_id,
          account_name       = EXCLUDED.account_name,
          username           = COALESCE(EXCLUDED.username, public.social_accounts.username),
          ig_user_token      = EXCLUDED.ig_user_token,
          access_token       = EXCLUDED.access_token,
          token_expires_at   = EXCLUDED.token_expires_at,
          linked_page_id     = EXCLUDED.linked_page_id,
          is_active          = true,
          is_system_user     = false,
          last_sync_at       = now(),
          updated_at         = now();
  END LOOP;

  -- Upsert threads rows.
  FOR v_thread IN SELECT * FROM jsonb_array_elements(COALESCE(p_threads, '[]'::jsonb))
  LOOP
    INSERT INTO public.social_accounts (
      user_id, company_id, meta_connection_id,
      platform, platform_user_id,
      account_name, username,
      threads_token, token_expires_at,
      linked_page_id, linked_ig_business_id,
      is_active, is_system_user,
      last_sync_at, created_at, updated_at,
      access_token
    )
    VALUES (
      v_user_id, v_company_id, v_connection_id,
      'threads',
      v_thread->>'threads_user_id',
      COALESCE(v_thread->>'account_name', 'Threads'),
      v_thread->>'username',
      v_thread->>'threads_token',
      v_token_expires_at,
      v_thread->>'linked_page_id',
      v_thread->>'linked_ig_business_id',
      true, false,
      now(), now(), now(),
      v_thread->>'threads_token'
    )
    ON CONFLICT (company_id, platform, platform_user_id) DO UPDATE
      SET meta_connection_id    = EXCLUDED.meta_connection_id,
          account_name          = EXCLUDED.account_name,
          username              = COALESCE(EXCLUDED.username, public.social_accounts.username),
          threads_token         = EXCLUDED.threads_token,
          access_token          = EXCLUDED.access_token,
          token_expires_at      = EXCLUDED.token_expires_at,
          linked_page_id        = EXCLUDED.linked_page_id,
          linked_ig_business_id = EXCLUDED.linked_ig_business_id,
          is_active             = true,
          is_system_user        = false,
          last_sync_at          = now(),
          updated_at            = now();
  END LOOP;

  RETURN v_connection_id;
END;
$$;


--
-- Name: omnivyra_log_decision_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnivyra_log_decision_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  detected_event_type TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO decision_events (decision_id, event_type, previous_value, new_value, changed_by)
    VALUES (NEW.id, 'created', NULL, to_jsonb(NEW), COALESCE(NEW.last_changed_by, 'system'));
    RETURN NEW;
  END IF;

  detected_event_type := 'updated';
  IF OLD.status <> 'resolved' AND NEW.status = 'resolved' THEN
    detected_event_type := 'resolved';
  ELSIF OLD.status IN ('resolved', 'ignored') AND NEW.status = 'open' THEN
    detected_event_type := 'reopened';
  END IF;

  INSERT INTO decision_events (decision_id, event_type, previous_value, new_value, changed_by)
  VALUES (NEW.id, detected_event_type, to_jsonb(OLD), to_jsonb(NEW), COALESCE(NEW.last_changed_by, 'system'));

  RETURN NEW;
END;
$$;


--
-- Name: omnivyra_prevent_decision_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnivyra_prevent_decision_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'decision_objects are immutable and cannot be deleted';
END;
$$;


--
-- Name: omnivyra_prevent_decision_overwrite(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnivyra_prevent_decision_overwrite() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(OLD.company_id, OLD.entity_type, OLD.entity_id, OLD.issue_type, OLD.title, OLD.description, OLD.evidence,
         OLD.impact_traffic, OLD.impact_conversion, OLD.impact_revenue, OLD.confidence_score, OLD.recommendation,
         OLD.action_type, OLD.action_payload, OLD.report_tier, OLD.source_service)
     IS DISTINCT FROM
     ROW(NEW.company_id, NEW.entity_type, NEW.entity_id, NEW.issue_type, NEW.title, NEW.description, NEW.evidence,
         NEW.impact_traffic, NEW.impact_conversion, NEW.impact_revenue, NEW.confidence_score, NEW.recommendation,
         NEW.action_type, NEW.action_payload, NEW.report_tier, NEW.source_service) THEN
    RAISE EXCEPTION 'Decision core fields are immutable. Create a new decision object instead of overwriting.';
  END IF;

  RETURN NEW;
END;
$$;


