--
-- Name: omnivyra_upsert_behavioral_analytics(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnivyra_upsert_behavioral_analytics(p_events jsonb DEFAULT '[]'::jsonb, p_conversions jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  inserted_events INTEGER := 0;
  inserted_conversions INTEGER := 0;
BEGIN
  INSERT INTO public.canonical_events (
    company_id,
    session_id,
    user_id,
    event_name,
    event_category,
    page_url,
    event_timestamp,
    source,
    metadata
  )
  SELECT
    (row_data->>'company_id')::uuid,
    row_data->>'session_id',
    row_data->>'user_id',
    row_data->>'event_name',
    row_data->>'event_category',
    NULLIF(row_data->>'page_url', ''),
    (row_data->>'event_timestamp')::timestamptz,
    (row_data->>'source')::public.canonical_event_source,
    COALESCE(row_data->'metadata', '{}'::jsonb)
  FROM jsonb_array_elements(COALESCE(p_events, '[]'::jsonb)) AS row_data
  ON CONFLICT ON CONSTRAINT canonical_events_company_session_name_timestamp_unique DO NOTHING;

  GET DIAGNOSTICS inserted_events = ROW_COUNT;

  INSERT INTO public.canonical_conversions (
    company_id,
    session_id,
    user_id,
    conversion_name,
    conversion_value,
    page_url,
    conversion_timestamp,
    source,
    metadata
  )
  SELECT
    (row_data->>'company_id')::uuid,
    row_data->>'session_id',
    row_data->>'user_id',
    row_data->>'conversion_name',
    NULLIF(row_data->>'conversion_value', '')::numeric,
    NULLIF(row_data->>'page_url', ''),
    (row_data->>'conversion_timestamp')::timestamptz,
    (row_data->>'source')::public.canonical_event_source,
    COALESCE(row_data->'metadata', '{}'::jsonb)
  FROM jsonb_array_elements(COALESCE(p_conversions, '[]'::jsonb)) AS row_data
  ON CONFLICT ON CONSTRAINT canonical_conversions_company_session_name_timestamp_unique DO NOTHING;

  GET DIAGNOSTICS inserted_conversions = ROW_COUNT;

  RETURN jsonb_build_object(
    'events_inserted', inserted_events,
    'conversions_inserted', inserted_conversions
  );
END;
$$;


--
-- Name: omnivyra_validate_decision_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnivyra_validate_decision_action() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  required_fields TEXT[];
  required_field  TEXT;
BEGIN
  SELECT ar.required_payload_fields
  INTO required_fields
  FROM action_registry ar
  WHERE ar.action_type = NEW.action_type
    AND ar.is_active = TRUE;

  IF required_fields IS NULL THEN
    RAISE EXCEPTION 'Decision action_type % is not registered or inactive', NEW.action_type;
  END IF;

  FOREACH required_field IN ARRAY required_fields LOOP
    IF jsonb_typeof(NEW.action_payload) <> 'object' OR NOT (NEW.action_payload ? required_field) THEN
      RAISE EXCEPTION 'Decision action_payload missing required field % for action_type %', required_field, NEW.action_type;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: omnivyra_validate_decision_object_entity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnivyra_validate_decision_object_entity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.entity_type = 'global' THEN
    IF NEW.entity_id IS NOT NULL THEN
      RAISE EXCEPTION 'Global decision objects must not include entity_id';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.entity_id IS NULL THEN
    RAISE EXCEPTION 'Non-global decision objects must include entity_id';
  END IF;

  IF NEW.entity_type = 'page' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM canonical_pages p
      WHERE p.id = NEW.entity_id
        AND p.company_id = NEW.company_id
    ) THEN
      RAISE EXCEPTION 'Decision object entity_id % is not a page in company %', NEW.entity_id, NEW.company_id;
    END IF;
  ELSIF NEW.entity_type = 'session' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM canonical_sessions s
      WHERE s.id = NEW.entity_id
        AND s.company_id = NEW.company_id
    ) THEN
      RAISE EXCEPTION 'Decision object entity_id % is not a session in company %', NEW.entity_id, NEW.company_id;
    END IF;
  ELSIF NEW.entity_type = 'campaign' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM campaigns c
      WHERE c.id = NEW.entity_id
        AND c.company_id = NEW.company_id
    ) THEN
      RAISE EXCEPTION 'Decision object entity_id % is not a campaign in company %', NEW.entity_id, NEW.company_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: populate_daily_plans_from_weekly(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.populate_daily_plans_from_weekly(campaign_uuid uuid, week_num integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  week_content record;
  inserted_count integer := 0;
  campaign_start date;
BEGIN
  SELECT start_date INTO campaign_start FROM public.campaigns WHERE id = campaign_uuid;

  FOR week_content IN
    SELECT * FROM public.content_plans
    WHERE campaign_id = campaign_uuid
      AND week_number = week_num
      AND refinement_status = 'finalized'
  LOOP
    INSERT INTO public.daily_content_plans (
      campaign_id, week_number, day_of_week, date, platform, content_type,
      title, content, hashtags, scheduled_time, source_week_content_id,
      ai_generated, status, priority
    ) VALUES (
      campaign_uuid,
      week_num,
      COALESCE(week_content.day_of_week, 'Monday'),
      COALESCE(campaign_start, current_date) + ((week_num - 1) * 7),
      week_content.platform,
      week_content.content_type,
      week_content.topic,
      COALESCE(week_content.content, ''),
      week_content.hashtags,
      '09:00',
      week_content.id,
      week_content.ai_generated,
      'planned',
      'medium'
    );

    inserted_count := inserted_count + 1;
  END LOOP;

  UPDATE public.weekly_content_refinements
  SET refinement_status = 'daily-populated',
      daily_plan_populated = true,
      updated_at = now()
  WHERE campaign_id = campaign_uuid
    AND week_number = week_num;

  UPDATE public.content_plans
  SET refinement_status = 'daily-populated',
      daily_plan_generated = true,
      daily_plan_generated_at = now(),
      updated_at = now()
  WHERE campaign_id = campaign_uuid
    AND week_number = week_num;

  RETURN inserted_count;
END;
$$;


--
-- Name: populate_weekly_content_from_ai_plan(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.populate_weekly_content_from_ai_plan(campaign_uuid uuid, ai_plan_data jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  week_data jsonb;
  content_item jsonb;
  inserted_count integer := 0;
  week_num integer;
  campaign_start date;
BEGIN
  SELECT start_date INTO campaign_start FROM public.campaigns WHERE id = campaign_uuid;

  FOR week_data IN SELECT * FROM jsonb_array_elements(COALESCE(ai_plan_data->'weeks', '[]'::jsonb))
  LOOP
    week_num := (week_data->>'week_number')::integer;

    FOR content_item IN SELECT * FROM jsonb_array_elements(COALESCE(week_data->'content', '[]'::jsonb))
    LOOP
      INSERT INTO public.content_plans (
        campaign_id, week_number, theme, focus_area, platform, content_type,
        topic, content, status, ai_generated, alignment_status, day_of_week,
        date, created_at, updated_at
      ) VALUES (
        campaign_uuid,
        week_num,
        week_data->>'theme',
        week_data->>'focus_area',
        content_item->>'platform',
        COALESCE(content_item->>'type', content_item->>'content_type', 'post'),
        content_item->>'topic',
        COALESCE(content_item->>'description', content_item->>'content', ''),
        'planned',
        true,
        'pending',
        content_item->>'day',
        COALESCE(campaign_start, current_date) + ((week_num - 1) * 7),
        now(),
        now()
      );

      inserted_count := inserted_count + 1;
    END LOOP;
  END LOOP;

  RETURN inserted_count;
END;
$$;


