--
-- Name: prune_rpa_artifacts(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_rpa_artifacts(p_limit integer DEFAULT 500) RETURNS TABLE(object_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
    WITH expired AS (
      SELECT id, object_path
      FROM   rpa_artifacts
      WHERE  retained_until < NOW()
      ORDER  BY retained_until ASC
      LIMIT  p_limit
      FOR    UPDATE SKIP LOCKED
    ),
    deleted AS (
      DELETE FROM rpa_artifacts t
      USING  expired e
      WHERE  t.id = e.id
      RETURNING e.object_path AS object_path
    )
    SELECT object_path FROM deleted;
END;
$$;


