--
-- Name: reap_community_ai_action_leases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reap_community_ai_action_leases() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_reaped_pending      integer := 0;
  v_reaped_dispatched   integer := 0;
  v_reaped_executing    integer := 0;
  v_lease_cleared       integer := 0;
BEGIN
  -- Browser-dispatch rows whose lease expired before an ack.
  WITH reaped AS (
    UPDATE community_ai_actions
    SET    status                    = 'failed',
           execution_result           = jsonb_build_object(
             'source',       'lease_reaper',
             'error_code',   'DISPATCH_LEASE_EXPIRED',
             'error_message','No extension ack before dispatch_lease_expires_at.'
           ),
           execution_correlation_id  = COALESCE(execution_correlation_id, gen_random_uuid()),
           dispatch_lease_id          = NULL,
           dispatch_lease_expires_at  = NULL,
           dispatch_lease_holder_id   = NULL,
           dispatch_acknowledged_at   = NULL,
           updated_at                 = NOW()
    WHERE  status                    = 'pending'
      AND  execution_mode            = 'browser'
      AND  dispatch_lease_expires_at IS NOT NULL
      AND  dispatch_lease_expires_at < NOW()
    RETURNING id, organization_id, platform, action_type, execution_correlation_id, execution_mode
  )
  INSERT INTO community_ai_execution_metric_events (
    organization_id, action_id, correlation_id, event_type, platform, action_type, execution_mode, metadata
  )
  SELECT organization_id, id, execution_correlation_id, 'lease_expired', platform, action_type, execution_mode,
         jsonb_build_object('phase', 'pending')
  FROM   reaped;
  GET DIAGNOSTICS v_reaped_pending = ROW_COUNT;

  -- dispatched / acknowledged rows whose lease expired in-flight.
  WITH reaped AS (
    UPDATE community_ai_actions
    SET    status                    = 'failed',
           execution_result           = jsonb_build_object(
             'source',       'lease_reaper',
             'error_code',   'DISPATCH_LEASE_EXPIRED_IN_FLIGHT',
             'error_message','Lease expired while command was in-flight on extension.'
           ),
           execution_correlation_id  = COALESCE(execution_correlation_id, gen_random_uuid()),
           dispatch_lease_id          = NULL,
           dispatch_lease_expires_at  = NULL,
           dispatch_lease_holder_id   = NULL,
           dispatch_acknowledged_at   = NULL,
           updated_at                 = NOW()
    WHERE  status IN ('dispatched', 'acknowledged')
      AND  dispatch_lease_expires_at IS NOT NULL
      AND  dispatch_lease_expires_at < NOW()
    RETURNING id, organization_id, platform, action_type, execution_correlation_id, execution_mode, status AS prior_status
  )
  INSERT INTO community_ai_execution_metric_events (
    organization_id, action_id, correlation_id, event_type, platform, action_type, execution_mode, metadata
  )
  SELECT organization_id, id, execution_correlation_id, 'lease_expired', platform, action_type, execution_mode,
         jsonb_build_object('phase', 'in_flight', 'prior_status', prior_status)
  FROM   reaped;
  GET DIAGNOSTICS v_reaped_dispatched = ROW_COUNT;

  -- executing rows older than the per-mode timeout.
  WITH reaped AS (
    UPDATE community_ai_actions
    SET    status                   = 'failed',
           execution_result         = jsonb_build_object(
             'source',       'lease_reaper',
             'error_code',   'EXECUTING_TIMEOUT',
             'error_message','Row stuck in executing past per-mode timeout.',
             'execution_mode', COALESCE(execution_mode, 'unknown')
           ),
           execution_correlation_id = COALESCE(execution_correlation_id, gen_random_uuid()),
           updated_at               = NOW()
    WHERE  status = 'executing'
      AND  (
            (execution_mode = 'api'     AND updated_at < NOW() - INTERVAL '30 seconds')
         OR (execution_mode = 'browser' AND updated_at < NOW() - INTERVAL '90 seconds')
         OR (execution_mode = 'rpa'     AND updated_at < NOW() - INTERVAL '5 minutes')
         OR (execution_mode NOT IN ('api','browser','rpa') AND updated_at < NOW() - INTERVAL '2 minutes')
         OR (execution_mode IS NULL AND updated_at < NOW() - INTERVAL '2 minutes')
      )
    RETURNING id, organization_id, platform, action_type, execution_correlation_id, execution_mode
  )
  INSERT INTO community_ai_execution_metric_events (
    organization_id, action_id, correlation_id, event_type, platform, action_type, execution_mode, metadata
  )
  SELECT organization_id, id, execution_correlation_id, 'lease_expired', platform, action_type, execution_mode,
         jsonb_build_object('phase', 'executing_timeout')
  FROM   reaped;
  GET DIAGNOSTICS v_reaped_executing = ROW_COUNT;

  WITH cleared AS (
    UPDATE community_ai_actions
    SET    dispatch_lease_id         = NULL,
           dispatch_lease_expires_at = NULL,
           dispatch_lease_holder_id  = NULL,
           dispatch_acknowledged_at  = NULL
    WHERE  status IN ('executed', 'sent_unverified', 'failed', 'skipped', 'blocked')
      AND  (dispatch_lease_id IS NOT NULL
         OR dispatch_lease_expires_at IS NOT NULL
         OR dispatch_lease_holder_id IS NOT NULL
         OR dispatch_acknowledged_at IS NOT NULL)
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_lease_cleared FROM cleared;

  RETURN jsonb_build_object(
    'reaped_pending',    v_reaped_pending,
    'reaped_dispatched', v_reaped_dispatched,
    'reaped_executing',  v_reaped_executing,
    'lease_cleared',     v_lease_cleared,
    'reaped_at',         NOW()
  );
END;
$$;


--
-- Name: record_email_event(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_email_event(p_job_id uuid, p_event_type text, p_metadata jsonb DEFAULT NULL::jsonb, p_failure_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_job email_jobs%ROWTYPE;
BEGIN
  SELECT * INTO v_job FROM email_jobs WHERE id = p_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'EMAIL_JOB_NOT_FOUND';
  END IF;

  INSERT INTO email_events (
    job_id,
    invitation_id,
    recipient_email,
    template_key,
    event_type,
    failure_reason,
    retry_count,
    correlation_id,
    metadata
  ) VALUES (
    p_job_id,
    v_job.invitation_id,
    v_job.recipient_email,
    v_job.template_key,
    p_event_type,
    p_failure_reason,
    v_job.retry_count,
    v_job.correlation_id,
    p_metadata
  );
END;
$$;


--
-- Name: record_payment_provider_event(text, text, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payment_provider_event(p_provider text, p_provider_event_id text, p_event_type text, p_purchase_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_event payment_provider_events%ROWTYPE;
BEGIN
  IF p_provider IS NULL OR btrim(p_provider) = '' THEN
    RAISE EXCEPTION 'payment provider is required';
  END IF;
  IF p_provider_event_id IS NULL OR btrim(p_provider_event_id) = '' THEN
    RAISE EXCEPTION 'provider_event_id is required';
  END IF;

  INSERT INTO payment_provider_events (
    provider,
    provider_event_id,
    event_type,
    purchase_id,
    organization_id,
    payload
  )
  VALUES (
    p_provider,
    p_provider_event_id,
    p_event_type,
    p_purchase_id,
    p_organization_id,
    COALESCE(p_payload, '{}'::jsonb)
  )
  ON CONFLICT (provider, provider_event_id) DO UPDATE
    SET processing_status = payment_provider_events.processing_status
  RETURNING * INTO v_event;

  RETURN row_to_json(v_event)::jsonb;
END;
$$;


--
-- Name: refresh_community_ai_execution_metrics_daily(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_community_ai_execution_metrics_daily(p_window_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_rows_upserted integer := 0;
BEGIN
  WITH agg AS (
    SELECT
      organization_id,
      COALESCE(platform,    '') AS platform,
      COALESCE(action_type, '') AS action_type,
      (created_at AT TIME ZONE 'UTC')::date AS bucket_date,
      COUNT(*) FILTER (WHERE event_type = 'execution_started')   AS started_count,
      COUNT(*) FILTER (WHERE event_type = 'execution_success')   AS success_count,
      COUNT(*) FILTER (WHERE event_type = 'execution_failed')    AS failure_count,
      COUNT(*) FILTER (WHERE event_type = 'fallback_triggered')  AS fallback_count,
      COUNT(*) FILTER (WHERE event_type = 'lease_expired')       AS lease_expired_count,
      COUNT(*) FILTER (WHERE event_type = 'ack_received')        AS ack_count
    FROM   community_ai_execution_metric_events
    WHERE  created_at >= NOW() - (p_window_days || ' days')::INTERVAL
    GROUP  BY organization_id, platform, action_type, bucket_date
  )
  INSERT INTO community_ai_execution_metrics_daily AS t (
    organization_id, platform, action_type, bucket_date,
    started_count, success_count, failure_count, fallback_count,
    lease_expired_count, ack_count, refreshed_at
  )
  SELECT organization_id, platform, action_type, bucket_date,
         started_count, success_count, failure_count, fallback_count,
         lease_expired_count, ack_count, NOW()
  FROM   agg
  ON CONFLICT (organization_id, platform, action_type, bucket_date)
  DO UPDATE SET
    started_count       = EXCLUDED.started_count,
    success_count       = EXCLUDED.success_count,
    failure_count       = EXCLUDED.failure_count,
    fallback_count      = EXCLUDED.fallback_count,
    lease_expired_count = EXCLUDED.lease_expired_count,
    ack_count           = EXCLUDED.ack_count,
    refreshed_at        = NOW();

  GET DIAGNOSTICS v_rows_upserted = ROW_COUNT;

  RETURN jsonb_build_object(
    'rows_upserted', v_rows_upserted,
    'window_days',   p_window_days,
    'refreshed_at',  NOW()
  );
END;
$$;


--
-- Name: replace_thread_children(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_thread_children(p_root_id uuid, p_children jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_root             scheduled_posts%ROWTYPE;
  v_idx              int;
  v_node             jsonb;
  v_child_id         uuid;
  v_node_ids         uuid[] := ARRAY[]::uuid[];
  v_node_media_urls  text[];
  v_node_media_types text[];
BEGIN
  SELECT * INTO v_root
  FROM scheduled_posts
  WHERE id = p_root_id AND is_thread_start = TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'thread_root_not_found';
  END IF;

  DELETE FROM scheduled_posts WHERE parent_post_id = p_root_id;

  IF p_children IS NOT NULL AND jsonb_typeof(p_children) = 'array' THEN
    FOR v_idx IN 0 .. jsonb_array_length(p_children) - 1 LOOP
      v_node := p_children->v_idx;
      v_child_id := gen_random_uuid();
      v_node_media_urls := ARRAY(
        SELECT jsonb_array_elements_text(COALESCE(v_node->'media_urls', '[]'::jsonb))
      );
      v_node_media_types := ARRAY(
        SELECT jsonb_array_elements_text(COALESCE(v_node->'media_types', '[]'::jsonb))
      );
      INSERT INTO scheduled_posts (
        id, user_id, social_account_id, campaign_id,
        platform, content_type, content,
        media_urls, media_types,
        scheduled_for, status,
        parent_post_id, thread_position, is_thread_start,
        created_at, updated_at
      ) VALUES (
        v_child_id, v_root.user_id, v_root.social_account_id, v_root.campaign_id,
        v_root.platform, v_root.content_type, v_node->>'content',
        CASE WHEN array_length(v_node_media_urls, 1) > 0 THEN v_node_media_urls ELSE NULL END,
        CASE WHEN array_length(v_node_media_types, 1) > 0 THEN v_node_media_types ELSE NULL END,
        v_root.scheduled_for, 'draft',
        p_root_id, (v_node->>'position')::int, FALSE,
        now(), now()
      );
      v_node_ids := array_append(v_node_ids, v_child_id);
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'root_id',  p_root_id,
    'node_ids', to_jsonb(v_node_ids)
  );
END;
$$;


--
-- Name: required_approvals_for_action(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.required_approvals_for_action(p_action_type text, p_amount integer) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(
    (SELECT required_approvals
       FROM public.credit_action_approval_thresholds
      WHERE action_type = p_action_type
        AND is_active = true
        AND amount_threshold_credits <= COALESCE(p_amount, 0)
      ORDER BY amount_threshold_credits DESC
      LIMIT 1),
    1
  );
$$;


--
-- Name: schedule_lead_thread_recompute(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_lead_thread_recompute(p_thread_id uuid, p_organization_id uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
  INSERT INTO lead_thread_recompute_queue (thread_id, organization_id, scheduled_at)
  VALUES (p_thread_id, p_organization_id, NOW() + interval '5 seconds')
  ON CONFLICT (thread_id, organization_id)
  DO UPDATE SET scheduled_at = CASE
    WHEN EXCLUDED.scheduled_at < lead_thread_recompute_queue.scheduled_at - interval '2 seconds'
    THEN EXCLUDED.scheduled_at
    ELSE lead_thread_recompute_queue.scheduled_at
  END;
$$;


--
-- Name: security_create_secret(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.security_create_secret(p_secret text, p_name text, p_description text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'pg_temp'
    AS $$
DECLARE
  new_id uuid;
BEGIN
  IF p_secret IS NULL OR length(p_secret) = 0 THEN
    RAISE EXCEPTION 'security_create_secret: empty secret';
  END IF;
  IF p_name IS NULL OR length(p_name) = 0 THEN
    RAISE EXCEPTION 'security_create_secret: empty name';
  END IF;
  -- Defensive prefix to keep the security subsystem from clobbering
  -- secrets owned by other features.
  IF p_name NOT LIKE 'security:%' THEN
    RAISE EXCEPTION 'security_create_secret: name must start with "security:"';
  END IF;

  SELECT vault.create_secret(p_secret, p_name, p_description) INTO new_id;
  RETURN new_id;
END;
$$;


