CREATE FUNCTION public.security_get_secret(p_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'pg_temp'
    AS $$
DECLARE
  result text;
BEGIN
  SELECT ds.decrypted_secret
    INTO result
    FROM vault.decrypted_secrets AS ds
   WHERE ds.id = p_id
   LIMIT 1;
  RETURN result;
END;
$$;


