--
-- Name: sign_credit_action_approval(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_credit_action_approval(p_approval_id uuid, p_approver_id uuid, p_decision text, p_comment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_approval     public.credit_action_approvals%ROWTYPE;
  v_approve_count integer;
  v_reject_count integer;
BEGIN
  IF p_decision NOT IN ('approve', 'reject') THEN
    RAISE EXCEPTION 'invalid decision %', p_decision;
  END IF;

  SELECT * INTO v_approval FROM public.credit_action_approvals
    WHERE id = p_approval_id
    FOR UPDATE;

  IF v_approval.id IS NULL THEN
    RAISE EXCEPTION 'APPROVAL_NOT_FOUND: %', p_approval_id;
  END IF;
  IF v_approval.status NOT IN ('pending', 'approved') THEN
    RAISE EXCEPTION 'APPROVAL_NOT_ACTIONABLE: status=%', v_approval.status;
  END IF;
  IF v_approval.executed_at IS NOT NULL THEN
    RAISE EXCEPTION 'APPROVAL_ALREADY_EXECUTED';
  END IF;
  IF v_approval.expires_at < now() THEN
    UPDATE public.credit_action_approvals SET status = 'expired' WHERE id = p_approval_id;
    RAISE EXCEPTION 'APPROVAL_EXPIRED';
  END IF;
  IF v_approval.proposed_by = p_approver_id THEN
    -- Proposer cannot self-approve (segregation of duties)
    RAISE EXCEPTION 'APPROVAL_SELF_NOT_ALLOWED: proposer cannot sign their own request';
  END IF;

  INSERT INTO public.credit_action_approval_signatures (approval_id, approver_id, decision, comment)
  VALUES (p_approval_id, p_approver_id, p_decision, p_comment);

  SELECT
    count(*) FILTER (WHERE decision = 'approve'),
    count(*) FILTER (WHERE decision = 'reject')
  INTO v_approve_count, v_reject_count
  FROM public.credit_action_approval_signatures
  WHERE approval_id = p_approval_id;

  IF v_reject_count >= 1 THEN
    UPDATE public.credit_action_approvals
      SET status = 'rejected', rejected_at = now(), rejected_by = p_approver_id, rejection_reason = p_comment
      WHERE id = p_approval_id
      RETURNING * INTO v_approval;
  ELSIF v_approve_count >= v_approval.required_approvals THEN
    UPDATE public.credit_action_approvals
      SET status = 'approved', approval_threshold_met_at = now(), approvals_received = v_approve_count
      WHERE id = p_approval_id
      RETURNING * INTO v_approval;
  ELSE
    UPDATE public.credit_action_approvals
      SET approvals_received = v_approve_count
      WHERE id = p_approval_id
      RETURNING * INTO v_approval;
  END IF;

  RETURN jsonb_build_object(
    'id',                 v_approval.id,
    'status',             v_approval.status,
    'approvals_received', v_approval.approvals_received,
    'required_approvals', v_approval.required_approvals,
    'approve_count',      v_approve_count,
    'reject_count',       v_reject_count
  );
END;
$$;


--
-- Name: soft_delete_company(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soft_delete_company(p_company_id uuid, p_actor uuid, p_reason text) RETURNS TABLE(affected_users integer, revoked_roles integer, revoked_sessions integer)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_cascade RECORD;
  v_now     TIMESTAMPTZ := NOW();
BEGIN
  IF p_company_id IS NULL THEN
    RAISE EXCEPTION 'SOFT_DELETE_COMPANY_NULL_COMPANY';
  END IF;
  IF p_reason IS NULL OR LENGTH(TRIM(p_reason)) = 0 THEN
    RAISE EXCEPTION 'SOFT_DELETE_COMPANY_MISSING_REASON';
  END IF;

  -- Run the cascade; reuse the same audit reason.
  SELECT * INTO v_cascade FROM disable_company_cascade(p_company_id, p_actor, p_reason);

  UPDATE companies
    SET deleted_at = v_now
    WHERE id = p_company_id
      AND deleted_at IS NULL;

  RETURN QUERY SELECT v_cascade.affected_users, v_cascade.revoked_roles, v_cascade.revoked_sessions;
END;
$$;


--
-- Name: sync_blog_likes_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_blog_likes_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public_blogs SET likes_count = COALESCE(likes_count, 0) + 1 WHERE id = NEW.blog_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public_blogs SET likes_count = GREATEST(COALESCE(likes_count, 0) - 1, 0) WHERE id = OLD.blog_id;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: sync_company_id_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_company_id_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- If active_company_id was set/changed, mirror to company_id
  IF TG_OP = 'UPDATE' AND NEW.active_company_id IS DISTINCT FROM OLD.active_company_id THEN
    NEW.company_id := NEW.active_company_id;
  -- If company_id was set/changed (legacy code), mirror to active_company_id
  ELSIF TG_OP = 'UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id THEN
    NEW.active_company_id := NEW.company_id;
  -- On INSERT, sync whichever is set
  ELSIF TG_OP = 'INSERT' THEN
    IF NEW.active_company_id IS NOT NULL AND NEW.company_id IS NULL THEN
      NEW.company_id := NEW.active_company_id;
    ELSIF NEW.company_id IS NOT NULL AND NEW.active_company_id IS NULL THEN
      NEW.active_company_id := NEW.company_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


