--
-- Name: transition_campaign_stage(uuid, character varying, character varying, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_campaign_stage(campaign_uuid uuid, from_stage character varying, to_stage character varying, stage_data jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    thread_exists BOOLEAN;
BEGIN
    -- Update campaign stage
    UPDATE campaigns 
    SET current_stage = to_stage, 
        status = CASE 
            WHEN to_stage = 'active' THEN 'active'
            WHEN to_stage = 'completed' THEN 'completed'
            ELSE to_stage
        END,
        updated_at = NOW()
    WHERE id = campaign_uuid;
    
    -- Update AI thread with stage transition
    SELECT EXISTS(SELECT 1 FROM ai_threads WHERE campaign_id = campaign_uuid) INTO thread_exists;
    
    IF thread_exists THEN
        UPDATE ai_threads 
        SET stage = to_stage,
            context = context || jsonb_build_object(
                'previous_stages', COALESCE(context->'previous_stages', '[]'::jsonb) || jsonb_build_object(
                    'stage', from_stage,
                    'data', stage_data,
                    'timestamp', NOW()
                )
            ),
            updated_at = NOW()
        WHERE campaign_id = campaign_uuid;
    END IF;
    
    RETURN TRUE;
END;
$$;


