--
-- Name: trigger_domain_reminder_cron(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_domain_reminder_cron() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'extensions'
    AS $$
DECLARE
  v_url        TEXT;
  v_secret     TEXT;
  v_request_id bigint;
BEGIN
  SELECT decrypted_secret INTO v_url
  FROM vault.decrypted_secrets
  WHERE name = 'domain_reminder_cron_url'
  LIMIT 1;

  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = 'domain_reminder_cron_secret'
  LIMIT 1;

  IF v_url IS NULL OR length(trim(v_url)) = 0 THEN
    RAISE NOTICE 'trigger_domain_reminder_cron: vault secret domain_reminder_cron_url not set';
    RETURN NULL;
  END IF;

  SELECT net.http_post(
    url     := v_url,
    headers := CASE
      WHEN v_secret IS NOT NULL AND length(trim(v_secret)) > 0
        THEN jsonb_build_object('Authorization', 'Bearer ' || v_secret, 'Content-Type', 'application/json')
        ELSE jsonb_build_object('Content-Type', 'application/json')
      END,
    body                 := '{}'::jsonb,
    timeout_milliseconds := 30000
  ) INTO v_request_id;
  RETURN v_request_id;
END $$;


--
-- Name: FUNCTION trigger_domain_reminder_cron(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_domain_reminder_cron() IS 'Called by pg_cron every 5 minutes. Reads URL + bearer from supabase_vault and POSTs to the process-reminders endpoint. Returns the pg_net request id.';


--
-- Name: trigger_recover_stale_reports_cron(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_recover_stale_reports_cron() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'extensions', 'net'
    AS $$
DECLARE
  v_secret text;
  v_request_id bigint;
BEGIN
  SELECT decrypted_secret
    INTO v_secret
    FROM vault.decrypted_secrets
   WHERE name = 'cron_internal_metrics_secret'
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_secret IS NULL OR length(v_secret) = 0 THEN
    RAISE WARNING '[trigger_recover_stale_reports_cron] vault entry "cron_internal_metrics_secret" missing; recovery sweep skipped';
    RETURN NULL;
  END IF;

  SELECT net.http_post(
    url     := 'https://www.omnivyra.com/api/cron/recover-stale-reports',
    body    := '{}'::jsonb,
    params  := '{}'::jsonb,
    headers := jsonb_build_object(
      'x-cron-secret', v_secret,
      'Content-Type',  'application/json'
    ),
    timeout_milliseconds := 30000
  ) INTO v_request_id;

  RETURN v_request_id;
END;
$$;


--
-- Name: FUNCTION trigger_recover_stale_reports_cron(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_recover_stale_reports_cron() IS 'Scheduled by pg_cron job recover-stale-reports-cron every 5 min. Reads INTERNAL_METRICS_SECRET mirror from Supabase Vault entry cron_internal_metrics_secret and POSTs to the recover-stale-reports endpoint. Vault entry must be populated separately with the same value as the Vercel INTERNAL_METRICS_SECRET env var.';


