--
-- Name: update_weekly_alignment(uuid, integer, character varying, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_weekly_alignment(campaign_uuid uuid, week_num integer, new_status character varying, notes text DEFAULT NULL::text, reviewer_uuid uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE public.content_plans
  SET alignment_status = new_status,
      alignment_notes = COALESCE(notes, alignment_notes),
      reviewed_by = COALESCE(reviewer_uuid, reviewed_by),
      reviewed_at = CASE WHEN new_status IN ('aligned', 'completed') THEN now() ELSE reviewed_at END,
      updated_at = now()
  WHERE campaign_id = campaign_uuid
    AND week_number = week_num;

  RETURN true;
END;
$$;


--
-- Name: upsert_engagement_thread_memory_locked(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_engagement_thread_memory_locked(p_thread_id uuid, p_organization_id uuid, p_conversation_summary text, p_last_message_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM 1 FROM engagement_threads WHERE id = p_thread_id FOR UPDATE;

  INSERT INTO engagement_thread_memory (thread_id, organization_id, conversation_summary, last_message_id, updated_at)
  VALUES (p_thread_id, p_organization_id, p_conversation_summary, p_last_message_id, now())
  ON CONFLICT (thread_id)
  DO UPDATE SET
    organization_id = EXCLUDED.organization_id,
    conversation_summary = EXCLUDED.conversation_summary,
    last_message_id = EXCLUDED.last_message_id,
    updated_at = now();
END;
$$;


--
-- Name: upsert_engagement_thread_memory_locked(uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
