--
-- Name: ws3_protect_task_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ws3_protect_task_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.company_id IS DISTINCT FROM OLD.company_id
     OR NEW.lead_id IS DISTINCT FROM OLD.lead_id
     OR NEW.plan_task_id IS DISTINCT FROM OLD.plan_task_id
     OR NEW.planner_version IS DISTINCT FROM OLD.planner_version
     OR NEW.translation_version IS DISTINCT FROM OLD.translation_version
     OR NEW.governance_version IS DISTINCT FROM OLD.governance_version
     OR NEW.execution_runtime_version IS DISTINCT FROM OLD.execution_runtime_version
     OR NEW.materialized_at IS DISTINCT FROM OLD.materialized_at THEN
    RAISE EXCEPTION 'ws3_immutable_provenance: identity and version fields are immutable after materialisation'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ws3_reject_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ws3_reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'ws3_append_only: % is append-only; % is not permitted',
    TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: ws3_suppression_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ws3_suppression_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ws3_append_only: outreach_suppressions is append-only; DELETE is not permitted'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.company_id IS DISTINCT FROM OLD.company_id
     OR NEW.scope IS DISTINCT FROM OLD.scope
     OR NEW.value IS DISTINCT FROM OLD.value
     OR NEW.reason IS DISTINCT FROM OLD.reason
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'ws3_suppression_immutable: only revoked_at/revoked_by may be updated'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


