);


--
-- Name: ai_suggestion_acceptance_rate; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ai_suggestion_acceptance_rate AS
 SELECT organization_id,
    COALESCE(platform, ''::text) AS platform,
    COALESCE(action_type, ''::text) AS action_type,
    COALESCE(model, ''::text) AS model,
    count(*) AS shown_count,
    sum(
        CASE
            WHEN (accepted_at IS NOT NULL) THEN 1
            ELSE 0
        END) AS accepted_count,
    sum(
        CASE
            WHEN (rejected_at IS NOT NULL) THEN 1
            ELSE 0
        END) AS rejected_count,
        CASE
            WHEN (count(*) = 0) THEN NULL::numeric
            ELSE round(((100.0 * (sum(
            CASE
                WHEN (accepted_at IS NOT NULL) THEN 1
                ELSE 0
            END))::numeric) / (count(*))::numeric), 2)
        END AS acceptance_rate_pct
   FROM public.ai_suggestions
  GROUP BY organization_id, COALESCE(platform, ''::text), COALESCE(action_type, ''::text), COALESCE(model, ''::text);


--
-- Name: VIEW ai_suggestion_acceptance_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.ai_suggestion_acceptance_rate IS 'Per (org, platform, action_type, model): shown / accepted / rejected counts and acceptance_rate_pct.';


