    score_sum numeric DEFAULT 0 NOT NULL,
    avg_score numeric GENERATED ALWAYS AS (
CASE
    WHEN (post_count > 0) THEN round((score_sum / (post_count)::numeric), 1)
    ELSE (0)::numeric
END) STORED,
    prior_rank smallint DEFAULT 2 NOT NULL,
    prior_note text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT angle_industry_matrix_angle_type_check CHECK ((angle_type = ANY (ARRAY['analytical'::text, 'contrarian'::text, 'strategic'::text]))),
    CONSTRAINT angle_industry_matrix_prior_rank_check CHECK (((prior_rank >= 1) AND (prior_rank <= 3)))
);


