--
-- Name: blog_performance_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.blog_performance_summary WITH (security_invoker='true') AS
 SELECT blog_id,
    count(*) AS session_count,
    round(avg(time_seconds)) AS avg_time_seconds,
    round(avg(scroll_depth)) AS avg_scroll_depth,
    round(avg(
        CASE
            WHEN completed THEN 100.0
            ELSE 0.0
        END)) AS completion_rate,
    count(*) FILTER (WHERE completed) AS completed_count,
    max(updated_at) AS last_session_at
   FROM public.blog_read_sessions
  GROUP BY blog_id;


