--
-- Name: decision_objects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.decision_objects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid,
    issue_type text NOT NULL,
    title text NOT NULL,
    description text NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    impact_traffic smallint NOT NULL,
    impact_conversion smallint NOT NULL,
    impact_revenue smallint NOT NULL,
    confidence_score numeric(4,3) NOT NULL,
    recommendation text NOT NULL,
    action_type text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    ignored_at timestamp with time zone,
    report_tier text NOT NULL,
    source_service text NOT NULL,
    action_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_changed_by text DEFAULT 'system'::text NOT NULL,
    priority_score smallint DEFAULT 0 NOT NULL,
    effort_score smallint DEFAULT 1 NOT NULL,
    execution_score numeric(12,4) GENERATED ALWAYS AS ((((impact_revenue)::numeric * confidence_score) / (GREATEST((effort_score)::integer, 1))::numeric)) STORED,
    CONSTRAINT decision_objects_action_payload_shape CHECK ((jsonb_typeof(action_payload) = ANY (ARRAY['object'::text, 'array'::text]))),
    CONSTRAINT decision_objects_action_type_not_blank CHECK ((length(btrim(action_type)) > 0)),
    CONSTRAINT decision_objects_confidence_valid CHECK (((confidence_score >= (0)::numeric) AND (confidence_score <= (1)::numeric))),
    CONSTRAINT decision_objects_description_not_blank CHECK ((length(btrim(description)) > 0)),
    CONSTRAINT decision_objects_effort_score_valid CHECK (((effort_score >= 0) AND (effort_score <= 100))),
    CONSTRAINT decision_objects_entity_type_valid CHECK ((entity_type = ANY (ARRAY['page'::text, 'session'::text, 'campaign'::text, 'lead'::text, 'revenue_event'::text, 'keyword'::text, 'content_cluster'::text, 'global'::text]))),
    CONSTRAINT decision_objects_evidence_shape CHECK ((jsonb_typeof(evidence) = ANY (ARRAY['object'::text, 'array'::text]))),
    CONSTRAINT decision_objects_global_entity_shape CHECK ((((entity_type = 'global'::text) AND (entity_id IS NULL)) OR ((entity_type <> 'global'::text) AND (entity_id IS NOT NULL)))),
    CONSTRAINT decision_objects_impact_conversion_valid CHECK (((impact_conversion >= 0) AND (impact_conversion <= 100))),
    CONSTRAINT decision_objects_impact_revenue_valid CHECK (((impact_revenue >= 0) AND (impact_revenue <= 100))),
    CONSTRAINT decision_objects_impact_traffic_valid CHECK (((impact_traffic >= 0) AND (impact_traffic <= 100))),
    CONSTRAINT decision_objects_issue_type_not_blank CHECK ((length(btrim(issue_type)) > 0)),
    CONSTRAINT decision_objects_last_changed_by_valid CHECK ((last_changed_by = ANY (ARRAY['system'::text, 'user'::text]))),
    CONSTRAINT decision_objects_priority_score_valid CHECK (((priority_score >= 0) AND (priority_score <= 100))),
    CONSTRAINT decision_objects_recommendation_not_blank CHECK ((length(btrim(recommendation)) > 0)),
    CONSTRAINT decision_objects_report_tier_valid CHECK ((report_tier = ANY (ARRAY['snapshot'::text, 'growth'::text, 'deep'::text]))),
    CONSTRAINT decision_objects_source_service_not_blank CHECK ((length(btrim(source_service)) > 0)),
    CONSTRAINT decision_objects_status_valid CHECK ((status = ANY (ARRAY['open'::text, 'resolved'::text, 'ignored'::text]))),
    CONSTRAINT decision_objects_title_not_blank CHECK ((length(btrim(title)) > 0))
);

ALTER TABLE ONLY public.decision_objects FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE decision_objects; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.decision_objects IS 'Canonical intelligence contract. Every future issue must resolve to: Issue -> Evidence -> Impact -> Confidence -> Recommendation -> Action.';


--
-- Name: COLUMN decision_objects.evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.decision_objects.evidence IS 'Structured JSON evidence only. Store source metrics, page/session facts, excerpts, or trace data required to justify the decision.';


--
-- Name: COLUMN decision_objects.report_tier; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.decision_objects.report_tier IS 'Canonical report tier this decision belongs to: snapshot, growth, or deep.';


--
-- Name: COLUMN decision_objects.source_service; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.decision_objects.source_service IS 'Backend service that generated the decision object. Used for enforcement, refresh, and tracing.';


--
-- Name: COLUMN decision_objects.action_payload; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.decision_objects.action_payload IS 'Structured execution payload consumed by activation flows. Must exist for every decision object.';


--
-- Name: omnivyra_decision_feature_base_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.omnivyra_decision_feature_base_view WITH (security_invoker='on') AS
 SELECT id,
    company_id,
    report_tier,
    source_service,
    entity_type,
    entity_id,
    issue_type AS canonical_issue_type,
    issue_type AS source_issue_type,
    title,
    description,
    evidence,
    impact_traffic,
    impact_conversion,
    impact_revenue,
    priority_score,
    effort_score,
    execution_score,
    confidence_score,
    recommendation,
    action_type,
    action_payload,
    status,
    last_changed_by,
    created_at,
    updated_at,
    resolved_at,
    ignored_at
   FROM public.decision_objects d;


--
-- Name: campaign_insights_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.campaign_insights_view WITH (security_invoker='on') AS
 SELECT id,
    company_id,
    report_tier,
    source_service,
    entity_type,
    entity_id,
    canonical_issue_type AS issue_type,
    title,
    description,
    evidence,
    impact_traffic,
    impact_conversion,
    impact_revenue,
    priority_score,
    effort_score,
    execution_score,
    confidence_score,
    recommendation,
    action_type,
    action_payload,
    status,
    last_changed_by,
    created_at,
    updated_at,
    resolved_at,
    ignored_at
   FROM public.omnivyra_decision_feature_base_view
  WHERE (entity_type = 'campaign'::text);


