--
-- Name: COLUMN companies.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.companies.status IS 'Operational lifecycle flag for the company. ''active'' = operational, ''inactive'' = disabled (set by disable_company_cascade). NOT a soft-delete — see companies.deleted_at for that. Original DDL pre-dates the migrations tree; declared here by 20260642_legacy_baseline_columns.sql.';


--
-- Name: COLUMN companies.deleted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.companies.deleted_at IS 'Soft-delete tombstone. NULL = live. Set by soft_delete_company RPC. Distinct from status (active|inactive), which is the reversible operational flag. Soft-deleted companies cannot be the target of new role assignments, sessions, or invitations.';


--
-- Name: canonical_company_entities; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.canonical_company_entities AS
 SELECT c.id,
    c.name,
    COALESCE(preferred.primary_domain, NULLIF(btrim(c.website_domain), ''::text)) AS domain,
    c.created_at
   FROM (public.companies c
     LEFT JOIN LATERAL ( SELECT d.primary_domain
           FROM public.canonical_domains d
          WHERE (d.company_id = c.id)
          ORDER BY d.verified DESC, d.created_at
         LIMIT 1) preferred ON (true));


--
-- Name: VIEW canonical_company_entities; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.canonical_company_entities IS 'Mapping view exposing the canonical company shape (id, name, domain, created_at) without breaking existing companies/company_domains usage.';


