--
-- Name: community_ai_execution_success_rate; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.community_ai_execution_success_rate AS
 SELECT organization_id,
    COALESCE(platform, ''::text) AS platform,
    COALESCE(action_type, ''::text) AS action_type,
    sum(
        CASE
            WHEN (status = 'executed'::text) THEN 1
            ELSE 0
        END) AS executed_count,
    sum(
        CASE
            WHEN (status = 'sent_unverified'::text) THEN 1
            ELSE 0
        END) AS sent_unverified_count,
    sum(
        CASE
            WHEN (status = 'failed'::text) THEN 1
            ELSE 0
        END) AS failed_count,
    sum(
        CASE
            WHEN (status = ANY (ARRAY['executed'::text, 'sent_unverified'::text, 'failed'::text])) THEN 1
            ELSE 0
        END) AS total_terminal,
        CASE
            WHEN (sum(
            CASE
                WHEN (status = ANY (ARRAY['executed'::text, 'sent_unverified'::text, 'failed'::text])) THEN 1
                ELSE 0
            END) = 0) THEN NULL::numeric
            ELSE round(((100.0 * (sum(
            CASE
                WHEN (status = ANY (ARRAY['executed'::text, 'sent_unverified'::text])) THEN 1
                ELSE 0
            END))::numeric) / (NULLIF(sum(
            CASE
                WHEN (status = ANY (ARRAY['executed'::text, 'sent_unverified'::text, 'failed'::text])) THEN 1
                ELSE 0
            END), 0))::numeric), 2)
        END AS success_rate_pct,
        CASE
            WHEN (sum(
            CASE
                WHEN (status = ANY (ARRAY['executed'::text, 'sent_unverified'::text, 'failed'::text])) THEN 1
                ELSE 0
            END) = 0) THEN NULL::numeric
            ELSE round(((100.0 * (sum(
            CASE
                WHEN (status = 'executed'::text) THEN 1
                ELSE 0
            END))::numeric) / (NULLIF(sum(
            CASE
                WHEN (status = ANY (ARRAY['executed'::text, 'sent_unverified'::text, 'failed'::text])) THEN 1
                ELSE 0
            END), 0))::numeric), 2)
        END AS confirmed_rate_pct
   FROM public.community_ai_actions
  WHERE (status = ANY (ARRAY['executed'::text, 'sent_unverified'::text, 'failed'::text]))
  GROUP BY organization_id, COALESCE(platform, ''::text), COALESCE(action_type, ''::text);


--
-- Name: VIEW community_ai_execution_success_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.community_ai_execution_success_rate IS 'Per (org, platform, action_type): executed vs sent_unverified vs failed counts and two ratios — success_rate_pct (executed+sent_unverified) and confirmed_rate_pct (executed only).';


