--
-- Name: community_ai_network_intelligence; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.community_ai_network_intelligence WITH (security_invoker='true') AS
 SELECT du.tenant_id,
    du.organization_id,
    du.platform,
    du.id AS discovered_user_id,
    du.discovery_source,
    du.first_seen_at,
    du.last_seen_at,
    du.classification,
    du.eligible_for_engagement AS eligibility,
    last_action.playbook_id,
    last_action.playbook_name,
    (playbook.automation_levels ->> 'network_expansion'::text) AS automation_level,
    COALESCE(action_counts.total_actions_created, (0)::bigint) AS total_actions_created,
    COALESCE(action_counts.total_actions_executed, (0)::bigint) AS total_actions_executed,
    last_action.action_type AS last_action_type,
    last_action.created_at AS last_action_at
   FROM (((public.community_ai_discovered_users du
     LEFT JOIN LATERAL ( SELECT count(*) AS total_actions_created,
            count(*) FILTER (WHERE (actions.status = 'executed'::text)) AS total_actions_executed
           FROM public.community_ai_actions actions
          WHERE (actions.discovered_user_id = du.id)) action_counts ON (true))
     LEFT JOIN LATERAL ( SELECT actions.action_type,
            actions.created_at,
            actions.playbook_id,
            actions.playbook_name
           FROM public.community_ai_actions actions
          WHERE (actions.discovered_user_id = du.id)
          ORDER BY actions.created_at DESC NULLS LAST
         LIMIT 1) last_action ON (true))
     LEFT JOIN public.community_ai_playbooks playbook ON (((playbook.id = last_action.playbook_id) AND (playbook.tenant_id = du.tenant_id) AND (playbook.organization_id = du.organization_id))));


