--
-- Name: company_financial_reconciliation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.company_financial_reconciliation AS
 WITH credits_consumed AS (
         SELECT credit_transactions.organization_id,
            date_trunc('day'::text, credit_transactions.created_at) AS period_day,
            (sum(
                CASE
                    WHEN (credit_transactions.execution_phase = 'confirm'::text) THEN credit_transactions.credits_delta
                    ELSE 0
                END))::numeric AS credits_confirmed,
            (sum(
                CASE
                    WHEN (credit_transactions.execution_phase = 'release'::text) THEN credit_transactions.credits_delta
                    ELSE 0
                END))::numeric AS credits_released
           FROM public.credit_transactions
          GROUP BY credit_transactions.organization_id, (date_trunc('day'::text, credit_transactions.created_at))
        ), provider_cost_estimated AS (
         SELECT usage_events.organization_id,
            date_trunc('day'::text, usage_events.created_at) AS period_day,
            sum(COALESCE(usage_events.total_cost_usd, (0)::numeric)) AS provider_usd_estimated,
            (count(*))::integer AS usage_event_count
           FROM public.usage_events
          GROUP BY usage_events.organization_id, (date_trunc('day'::text, usage_events.created_at))
        ), adjustments AS (
         SELECT cost_reconciliation_adjustments.organization_id,
            date_trunc('day'::text, cost_reconciliation_adjustments.created_at) AS period_day,
            sum(cost_reconciliation_adjustments.adjustment_usd) AS adjustment_usd_sum,
            (count(*))::integer AS adjustment_count
           FROM public.cost_reconciliation_adjustments
          WHERE (cost_reconciliation_adjustments.organization_id IS NOT NULL)
          GROUP BY cost_reconciliation_adjustments.organization_id, (date_trunc('day'::text, cost_reconciliation_adjustments.created_at))
        )
 SELECT COALESCE(c.organization_id, p.organization_id, a.organization_id) AS organization_id,
    COALESCE(c.period_day, p.period_day, a.period_day) AS period_day,
    COALESCE(c.credits_confirmed, (0)::numeric) AS credits_confirmed,
    COALESCE(c.credits_released, (0)::numeric) AS credits_released,
    COALESCE(p.provider_usd_estimated, (0)::numeric) AS provider_usd_estimated,
    COALESCE(p.usage_event_count, 0) AS usage_event_count,
    COALESCE(a.adjustment_usd_sum, (0)::numeric) AS adjustment_usd_sum,
    COALESCE(a.adjustment_count, 0) AS adjustment_count,
    (COALESCE(p.provider_usd_estimated, (0)::numeric) + COALESCE(a.adjustment_usd_sum, (0)::numeric)) AS provider_usd_effective
   FROM ((credits_consumed c
     FULL JOIN provider_cost_estimated p ON (((p.organization_id = c.organization_id) AND (p.period_day = c.period_day))))
     FULL JOIN adjustments a ON (((a.organization_id = COALESCE(c.organization_id, p.organization_id)) AND (a.period_day = COALESCE(c.period_day, p.period_day)))));


--
-- Name: VIEW company_financial_reconciliation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.company_financial_reconciliation IS 'Per-company per-day aggregation joining credit settlement, estimated provider USD, and reconciliation adjustments. Read-only; deterministic; no historical mutation. Adjustments apply forward via cost_reconciliation_adjustments; the credit ledger is never mutated.';


