    CONSTRAINT company_workforce_profile_review_status_valid CHECK ((review_status = ANY (ARRAY['missing'::text, 'unknown'::text, 'inferred'::text, 'user_confirmed'::text, 'stale'::text, 'needs_review'::text, 'conflicting'::text, 'deprecated'::text, 'system_generated'::text]))),
    CONSTRAINT company_workforce_profile_source_signals_array CHECK ((jsonb_typeof(source_signals) = 'array'::text)),
    CONSTRAINT company_workforce_profile_source_valid CHECK ((source = ANY (ARRAY['user'::text, 'ai_inferred'::text, 'integration'::text, 'import'::text, 'system'::text, 'unknown'::text])))
);


