--

CREATE TABLE public.contact_governance_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    person_id uuid,
    target_normalized text,
    target_raw text,
    channel text NOT NULL,
    governance_type text NOT NULL,
    source text NOT NULL,
    source_record_id uuid,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    effective_from timestamp with time zone DEFAULT now() NOT NULL,
    effective_until timestamp with time zone,
    revoked_at timestamp with time zone,
    revoked_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT contact_governance_channel_dnc_is_specific CHECK (((governance_type <> 'dnc_channel'::text) OR (channel <> '*'::text))),
    CONSTRAINT contact_governance_channel_not_blank CHECK ((length(btrim(channel)) > 0)),
    CONSTRAINT contact_governance_evidence_object CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT contact_governance_has_anchor CHECK (((person_id IS NOT NULL) OR ((target_normalized IS NOT NULL) AND (length(btrim(target_normalized)) > 0)))),
    CONSTRAINT contact_governance_period_ordered CHECK (((effective_until IS NULL) OR (effective_until > effective_from))),
    CONSTRAINT contact_governance_permanent_is_all_channels CHECK (((governance_type <> 'dnc_permanent'::text) OR (channel = '*'::text))),
    CONSTRAINT contact_governance_revocation_coherent CHECK (((revoked_at IS NULL) = (revoked_reason IS NULL))),
    CONSTRAINT contact_governance_source_not_blank CHECK ((length(btrim(source)) > 0)),
    CONSTRAINT contact_governance_target_not_blank CHECK (((target_normalized IS NULL) OR (length(btrim(target_normalized)) > 0))),
    CONSTRAINT contact_governance_type_valid CHECK ((governance_type = ANY (ARRAY['dnc_permanent'::text, 'dnc_channel'::text, 'unsubscribe'::text, 'consent_withdrawn'::text, 'invalid_contact'::text, 'bounce_hard'::text, 'complaint'::text, 'deferred'::text, 'campaign_exclusion'::text]))),
    CONSTRAINT contact_governance_until_only_deferred CHECK (((effective_until IS NULL) OR (governance_type = 'deferred'::text)))
);


