    source_type text NOT NULL,
    provider_name text,
    model_name text,
    input_tokens integer,
    output_tokens integer,
    total_tokens integer,
    api_cost_usd numeric(20,10),
    credits_charged integer,
    credits_value_usd numeric(20,10),
    margin_usd numeric(20,10) GENERATED ALWAYS AS ((COALESCE(credits_value_usd, (0)::numeric) - COALESCE(api_cost_usd, (0)::numeric))) STORED,
    retry_attempt integer DEFAULT 1 NOT NULL,
    final_attempt boolean DEFAULT true NOT NULL,
    error_flag boolean DEFAULT false NOT NULL,
    error_type text,
    reference_type text,
    reference_id text,
    pricing_snapshot jsonb,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    input_cost_usd numeric,
    output_cost_usd numeric,
    final_price_usd numeric,
    ledger_hold_transaction_id uuid,
    CONSTRAINT unified_transactions_retry_attempt_check CHECK ((retry_attempt >= 1)),
    CONSTRAINT unified_transactions_source_type_check CHECK ((source_type = ANY (ARRAY['llm'::text, 'embedding'::text, 'cache'::text, 'external_api'::text, 'automation_execution'::text, 'system'::text, 'internal'::text]))),
    CONSTRAINT unified_txn_action_key_required CHECK (((action_key IS NOT NULL) OR (source_type = 'internal'::text))),
    CONSTRAINT unified_txn_cost_non_negative CHECK ((((api_cost_usd IS NULL) OR (api_cost_usd >= (0)::numeric)) AND ((credits_value_usd IS NULL) OR (credits_value_usd >= (0)::numeric)))),
    CONSTRAINT unified_txn_cost_required CHECK (((source_type = ANY (ARRAY['cache'::text, 'system'::text, 'internal'::text, 'automation_execution'::text])) OR (error_flag = true) OR (api_cost_usd IS NOT NULL))),
    CONSTRAINT unified_txn_tokens_non_negative CHECK ((((input_tokens IS NULL) OR (input_tokens >= 0)) AND ((output_tokens IS NULL) OR (output_tokens >= 0)) AND ((total_tokens IS NULL) OR (total_tokens >= 0))))
);


--
-- Name: TABLE unified_transactions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.unified_transactions IS 'CORE LEDGER — DO NOT ALTER WITHOUT REVIEW. Single source of truth for cost + credits + margin per logical action. See docs/VARIABLE-COST-TRACKING-ROADMAP.md change protocol.';


--
-- Name: cost_margin_daily_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.cost_margin_daily_view AS
 SELECT (date_trunc('day'::text, created_at))::date AS day,
    sum(COALESCE(api_cost_usd, (0)::numeric)) AS total_api_cost_usd,
    sum(COALESCE(credits_value_usd, (0)::numeric)) AS total_credits_value_usd,
    sum(margin_usd) AS margin_usd,
    sum(margin_usd) FILTER (WHERE (margin_usd < (0)::numeric)) AS negative_margin_total_usd,
    count(*) AS event_count,
    count(*) FILTER (WHERE (margin_usd < (0)::numeric)) AS negative_margin_event_count
   FROM public.unified_transactions
  WHERE ((final_attempt = true) AND (created_at >= (CURRENT_DATE - '90 days'::interval)))
  GROUP BY ((date_trunc('day'::text, created_at))::date)
  ORDER BY ((date_trunc('day'::text, created_at))::date) DESC;


--
-- Name: VIEW cost_margin_daily_view; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.cost_margin_daily_view IS 'Daily cost / credits / margin rollup. Watch the total_api_cost vs credits_value delta per the first-14-days baseline.';


--
-- Name: cost_monitoring_daily_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.cost_monitoring_daily_view AS
 SELECT (date_trunc('day'::text, detected_at))::date AS day,
    anomaly_type,
    severity,
    count(*) AS anomaly_count
   FROM public.cost_anomalies
  WHERE (detected_at >= (CURRENT_DATE - '90 days'::interval))
  GROUP BY ((date_trunc('day'::text, detected_at))::date), anomaly_type, severity
  ORDER BY ((date_trunc('day'::text, detected_at))::date) DESC, (count(*)) DESC;


--
-- Name: VIEW cost_monitoring_daily_view; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.cost_monitoring_daily_view IS 'Daily anomaly rollup for the first-14-days monitoring baseline. Filter by anomaly_type = pricing_missing / unknown_action_key / cost_credit_mismatch per the escalation rules.';


