--
-- Name: decision_priority_queue; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.decision_priority_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    decision_id uuid NOT NULL,
    report_tier text NOT NULL,
    priority_score smallint NOT NULL,
    priority_rank integer NOT NULL,
    score_impact numeric(6,4) NOT NULL,
    score_confidence numeric(6,4) NOT NULL,
    score_revenue_linkage numeric(6,4) NOT NULL,
    score_urgency numeric(6,4) NOT NULL,
    model_version text NOT NULL,
    scored_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    priority_rationale text DEFAULT ''::text NOT NULL,
    priority_segment text DEFAULT 'strategic'::text NOT NULL,
    prioritization_mode text DEFAULT 'growth'::text NOT NULL,
    correlation_boost numeric(6,4) DEFAULT 0 NOT NULL,
    playbook_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT decision_priority_queue_correlation_boost_valid CHECK (((correlation_boost >= (0)::numeric) AND (correlation_boost <= (1)::numeric))),
    CONSTRAINT decision_priority_queue_model_version_not_blank CHECK ((length(btrim(model_version)) > 0)),
    CONSTRAINT decision_priority_queue_playbook_json_shape CHECK (((jsonb_typeof(playbook_json) = 'object'::text) AND (playbook_json ? 'objective'::text) AND (playbook_json ? 'steps'::text) AND (playbook_json ? 'estimated_effort'::text) AND (playbook_json ? 'expected_impact'::text) AND (playbook_json ? 'dependencies'::text) AND (jsonb_typeof((playbook_json -> 'steps'::text)) = 'array'::text) AND (jsonb_typeof((playbook_json -> 'expected_impact'::text)) = 'object'::text) AND (jsonb_typeof((playbook_json -> 'dependencies'::text)) = 'array'::text))),
    CONSTRAINT decision_priority_queue_prioritization_mode_valid CHECK ((prioritization_mode = ANY (ARRAY['growth'::text, 'efficiency'::text, 'risk'::text]))),
    CONSTRAINT decision_priority_queue_priority_rank_valid CHECK ((priority_rank > 0)),
    CONSTRAINT decision_priority_queue_priority_score_valid CHECK (((priority_score >= 0) AND (priority_score <= 100))),
    CONSTRAINT decision_priority_queue_priority_segment_valid CHECK ((priority_segment = ANY (ARRAY['quick_wins'::text, 'strategic'::text, 'risk'::text]))),
    CONSTRAINT decision_priority_queue_report_tier_valid CHECK ((report_tier = ANY (ARRAY['snapshot'::text, 'growth'::text, 'deep'::text]))),
    CONSTRAINT decision_priority_queue_score_confidence_valid CHECK (((score_confidence >= (0)::numeric) AND (score_confidence <= (1)::numeric))),
    CONSTRAINT decision_priority_queue_score_impact_valid CHECK (((score_impact >= (0)::numeric) AND (score_impact <= (1)::numeric))),
    CONSTRAINT decision_priority_queue_score_revenue_linkage_valid CHECK (((score_revenue_linkage >= (0)::numeric) AND (score_revenue_linkage <= (1)::numeric))),
    CONSTRAINT decision_priority_queue_score_urgency_valid CHECK (((score_urgency >= (0)::numeric) AND (score_urgency <= (1)::numeric)))
);


