--
-- Name: free_credits_activity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.free_credits_activity AS
 SELECT 'claim'::text AS source,
    fc.id,
    fc.user_id,
    fc.organization_id,
    u.email,
    fc.category,
    fc.credits_granted AS credits_amount,
    NULL::text AS reason,
    NULL::text AS granted_by_email,
    fc.claimed_at AS created_at
   FROM (public.free_credit_claims fc
     LEFT JOIN auth.users u ON ((u.id = fc.user_id)))
UNION ALL
 SELECT 'manual'::text AS source,
    mg.id,
    mg.user_id,
    mg.organization_id,
    u.email,
    mg.category,
    mg.credits_amount,
    mg.reason,
    ga.email AS granted_by_email,
    mg.created_at
   FROM ((public.manual_credit_grants mg
     LEFT JOIN auth.users u ON ((u.id = mg.user_id)))
     LEFT JOIN auth.users ga ON ((ga.id = mg.granted_by)))
UNION ALL
 SELECT 'access_request'::text AS source,
    ar.id,
    ar.user_id,
    ar.organization_id,
    ar.email,
    'domain_approval'::text AS category,
    COALESCE(ar.credits_granted_amount, 0) AS credits_amount,
    ar.admin_note AS reason,
    NULL::text AS granted_by_email,
    ar.reviewed_at AS created_at
   FROM public.access_requests ar
  WHERE ((ar.status = 'approved'::text) AND (COALESCE(ar.credits_granted_amount, 0) > 0));


