--

CREATE TABLE public.identity_claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    person_id uuid,
    account_id uuid,
    claim_type text NOT NULL,
    platform text,
    normalized_value text NOT NULL,
    raw_value text,
    source text DEFAULT 'manual'::text NOT NULL,
    source_reference text,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    confidence numeric,
    verification_state text DEFAULT 'unverified'::text NOT NULL,
    verified_at timestamp with time zone,
    observed_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    revoked_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT identity_claims_confidence_range CHECK (((confidence IS NULL) OR ((confidence >= (0)::numeric) AND (confidence <= (1)::numeric)))),
    CONSTRAINT identity_claims_evidence_object CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT identity_claims_platform_rule CHECK ((((claim_type = ANY (ARRAY['email'::text, 'phone'::text, 'domain'::text])) AND (platform IS NULL)) OR ((claim_type = ANY (ARRAY['external_profile'::text, 'external_id'::text])) AND (platform IS NOT NULL) AND (length(btrim(platform)) > 0)))),
    CONSTRAINT identity_claims_source_not_blank CHECK ((length(btrim(source)) > 0)),
    CONSTRAINT identity_claims_type_valid CHECK ((claim_type = ANY (ARRAY['email'::text, 'phone'::text, 'domain'::text, 'external_profile'::text, 'external_id'::text]))),
    CONSTRAINT identity_claims_value_is_normalized CHECK ((normalized_value = lower(normalized_value))),
    CONSTRAINT identity_claims_value_not_blank CHECK ((length(btrim(normalized_value)) > 0)),
    CONSTRAINT identity_claims_verification_valid CHECK ((verification_state = ANY (ARRAY['unverified'::text, 'verified'::text, 'rejected'::text]))),
    CONSTRAINT identity_claims_verified_coherent CHECK (((verification_state = 'verified'::text) = (verified_at IS NOT NULL)))
);


--
-- Name: TABLE identity_claims; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.identity_claims IS 'Durable, explainable identity assertions for unified_persons. Unique on (organization_id, claim_type, platform, normalized_value) NULLS NOT DISTINCT among non-revoked claims — tenant-scoped by construction. person_id is nullable so the shadow resolver can record an observation without asserting a person.';


