--

COMMENT ON COLUMN public.lead_attributions.asset_id IS 'Creator content asset id (content_assets.asset_id) carried via the omn_asset_id link param. Nullable; legacy/non-creator leads have none.';


--
-- Name: COLUMN lead_attributions.variant_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lead_attributions.variant_id IS 'A/B variant id carried via the omn_variant_id link param. Free-form text (variant experiment tracker is not a DB table). Nullable.';


--
-- Name: COLUMN lead_attributions.creator_strategy_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lead_attributions.creator_strategy_id IS 'Creator strategy id carried via the omn_strategy_id link param. Nullable; mirrors bolt_failure_summary.strategy_id semantics (best-effort).';


