--
-- Name: lead_intelligence_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.lead_intelligence_view WITH (security_invoker='on') AS
 SELECT id,
    company_id,
    report_tier,
    source_service,
    entity_type,
    entity_id,
    canonical_issue_type AS issue_type,
    title,
    description,
    evidence,
    impact_traffic,
    impact_conversion,
    impact_revenue,
    priority_score,
    effort_score,
    execution_score,
    confidence_score,
    recommendation,
    action_type,
    action_payload,
    status,
    last_changed_by,
    created_at,
    updated_at,
    resolved_at,
    ignored_at
   FROM public.omnivyra_decision_feature_base_view
  WHERE (entity_type = 'lead'::text);


