CREATE TABLE public.listening_configurations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    mode text DEFAULT 'manual_only'::text NOT NULL,
    platforms text[] DEFAULT ARRAY[]::text[] NOT NULL,
    keyword_count integer DEFAULT 0 NOT NULL,
    industry_category text,
    industry_volatility text,
    monthly_credit_ceiling integer DEFAULT 0 NOT NULL,
    daily_run_ceiling integer DEFAULT 1 NOT NULL,
    cooldown_minutes integer DEFAULT 60 NOT NULL,
    estimated_monthly_credits_min integer DEFAULT 0 NOT NULL,
    estimated_monthly_credits_max integer DEFAULT 0 NOT NULL,
    estimated_credits_per_run integer DEFAULT 0 NOT NULL,
    next_planned_run_at timestamp with time zone,
    last_run_at timestamp with time zone,
    last_confirmation_at timestamp with time zone,
    confirmed_by uuid,
    confirmed_estimate_hash text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT listening_configurations_ceilings_check CHECK (((monthly_credit_ceiling >= 0) AND (daily_run_ceiling >= 0) AND (cooldown_minutes >= 0))),
    CONSTRAINT listening_configurations_estimate_check CHECK (((estimated_monthly_credits_min >= 0) AND (estimated_monthly_credits_max >= estimated_monthly_credits_min))),
    CONSTRAINT listening_configurations_mode_check CHECK ((mode = ANY (ARRAY['manual_only'::text, 'daily'::text, 'alternate_days'::text, 'weekly'::text]))),
    CONSTRAINT listening_configurations_volatility_check CHECK (((industry_volatility IS NULL) OR (industry_volatility = ANY (ARRAY['high'::text, 'moderate'::text, 'low'::text]))))
);


