);


--
-- Name: market_pulse_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.market_pulse_view WITH (security_invoker='on') AS
 SELECT company_id,
    COALESCE(NULLIF(btrim((evidence ->> 'keyword'::text)), ''::text), NULLIF(btrim((evidence ->> 'content_cluster'::text)), ''::text), NULLIF(btrim((evidence ->> 'market_topic'::text)), ''::text), NULLIF(btrim((evidence ->> 'topic'::text)), ''::text), canonical_issue_type) AS pulse_key,
    canonical_issue_type AS issue_type,
    action_type,
    (count(*))::integer AS decision_count,
    round(avg(impact_traffic), 2) AS avg_impact_traffic,
    round(avg(impact_conversion), 2) AS avg_impact_conversion,
    round(avg(impact_revenue), 2) AS avg_impact_revenue,
    round(avg(confidence_score), 3) AS avg_confidence_score,
    round(max(execution_score), 4) AS max_execution_score,
    max(created_at) AS latest_decision_at
   FROM public.omnivyra_decision_feature_base_view
  WHERE ((status = 'open'::text) AND (canonical_issue_type = ANY (ARRAY['market_shift'::text, 'market_opportunity'::text, 'content_gap'::text, 'seo_gap'::text, 'keyword_opportunity'::text, 'impression_click_gap'::text, 'ranking_gap'::text, 'topic_gap'::text, 'weak_cluster_depth'::text, 'missing_supporting_content'::text])))
  GROUP BY company_id, COALESCE(NULLIF(btrim((evidence ->> 'keyword'::text)), ''::text), NULLIF(btrim((evidence ->> 'content_cluster'::text)), ''::text), NULLIF(btrim((evidence ->> 'market_topic'::text)), ''::text), NULLIF(btrim((evidence ->> 'topic'::text)), ''::text), canonical_issue_type), canonical_issue_type, action_type;


