--
-- Name: org_economics_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.org_economics_view AS
 SELECT organization_id,
    action_key,
    model_name,
    source_type,
    date_trunc('day'::text, created_at) AS day,
    sum(COALESCE(api_cost_usd, (0)::numeric)) AS total_api_cost_usd,
    sum(COALESCE(credits_charged, 0)) AS total_credits_used,
    sum(COALESCE(credits_value_usd, (0)::numeric)) AS credits_value_usd,
    sum(margin_usd) AS margin_usd,
    bool_or((margin_usd < (0)::numeric)) AS negative_margin_flag,
    sum(COALESCE(total_tokens, 0)) AS total_tokens,
    count(*) AS event_count,
    count(*) FILTER (WHERE error_flag) AS error_count
   FROM public.unified_transactions
  WHERE (final_attempt = true)
  GROUP BY organization_id, action_key, model_name, source_type, (date_trunc('day'::text, created_at));


