--
-- Name: TABLE pricing_intelligence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.pricing_intelligence IS 'ANALYTICS TABLE — DO NOT ALTER WITHOUT REVIEW. Weekly margin snapshot populated by runWeeklyPricingAnalysis().';


--
-- Name: pricing_health_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pricing_health_view AS
 WITH recent AS (
         SELECT pricing_intelligence.id,
            pricing_intelligence.action_key,
            pricing_intelligence.model_name,
            pricing_intelligence.week_start,
            pricing_intelligence.total_api_cost_usd,
            pricing_intelligence.total_credits_value_usd,
            pricing_intelligence.margin_usd,
            pricing_intelligence.margin_percent,
            pricing_intelligence.current_multiplier,
            pricing_intelligence.recommended_multiplier,
            pricing_intelligence.deviation_flag,
            pricing_intelligence.event_count,
            pricing_intelligence.created_at
           FROM public.pricing_intelligence
          WHERE (pricing_intelligence.week_start >= (CURRENT_DATE - '28 days'::interval))
        ), per_action AS (
         SELECT recent.action_key,
            avg(recent.margin_percent) FILTER (WHERE (recent.margin_percent IS NOT NULL)) AS avg_margin_percent,
            sum(recent.total_api_cost_usd) AS total_cost,
            sum(recent.total_credits_value_usd) AS total_credits,
            count(*) AS weeks_observed,
            bool_or(recent.deviation_flag) AS any_deviation
           FROM recent
          GROUP BY recent.action_key
        )
 SELECT action_key,
    avg_margin_percent,
    total_cost,
    total_credits,
    weeks_observed,
    any_deviation,
        CASE
            WHEN (avg_margin_percent IS NULL) THEN 'low'::text
            WHEN ((avg_margin_percent < 0.10) OR (avg_margin_percent > 0.70)) THEN 'high'::text
            WHEN ((avg_margin_percent < 0.20) OR (avg_margin_percent > 0.60)) THEN 'medium'::text
            ELSE 'low'::text
        END AS risk_level
   FROM per_action;


