    CONSTRAINT valid_domain CHECK (((domain)::text ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*([a-z]{2,})?$'::text)),
