    CONSTRAINT valid_report_type CHECK (((report_type)::text = ANY ((ARRAY['content_readiness'::character varying, 'competitor_analysis'::character varying, 'gap_analysis'::character varying, 'snapshot'::character varying, 'performance'::character varying, 'performance_intelligence'::character varying, 'growth'::character varying, 'strategic'::character varying])::text[])))
);


