--
-- Name: retention_candidates; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.retention_candidates AS
 SELECT 'report_score_history'::text AS table_name,
    rsh.company_id,
    rsh.observed_at,
    rsh.tenant_id
   FROM public.report_score_history rsh
UNION ALL
 SELECT 'report_provider_history'::text AS table_name,
    rph.company_id,
    rph.observed_at,
    NULL::text AS tenant_id
   FROM public.report_provider_history rph
UNION ALL
 SELECT 'audit_log'::text AS table_name,
    NULL::text AS company_id,
    al.occurred_at AS observed_at,
    al.tenant_id
   FROM public.audit_log al;


