--
-- Name: scheduled_posts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.scheduled_posts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    social_account_id uuid,
    campaign_id uuid,
    platform character varying(50) NOT NULL,
    content_type character varying(100) NOT NULL,
    title character varying(500),
    content text NOT NULL,
    hashtags text[],
    location character varying(200),
    media_urls text[],
    media_types character varying(20)[],
    media_sizes bigint[],
    media_formats character varying(10)[],
    video_duration integer,
    video_resolution character varying(20),
    video_aspect_ratio character varying(10),
    video_bitrate integer,
    video_fps integer,
    image_width integer,
    image_height integer,
    image_aspect_ratio character varying(10),
    audio_duration integer,
    audio_title character varying(200),
    audio_url character varying(500),
    parent_post_id uuid,
    thread_position integer,
    is_thread_start boolean DEFAULT false,
    stickers jsonb,
    scheduled_for timestamp with time zone NOT NULL,
    status character varying(50) DEFAULT 'draft'::character varying,
    published_at timestamp with time zone,
    post_url text,
    platform_post_id character varying(255),
    error_message text,
    retry_count integer DEFAULT 0,
    max_retries integer DEFAULT 3,
    next_retry_at timestamp with time zone,
    ai_score integer,
    uniqueness_score integer,
    repetition_score integer,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    priority integer DEFAULT 0,
    error_code character varying(100),
    repurpose_index integer DEFAULT 1,
    repurpose_total integer DEFAULT 1,
    repurpose_parent_execution_id text,
    idempotency_key text,
    execution_platform_id text,
    asset_hash text,
    publish_source text DEFAULT 'unknown'::text NOT NULL,
    execution_intent_id text,
    creator_attachment_metadata jsonb,
    thread_title text,
    design_attribution jsonb,
    youtube_privacy character varying,
    publish_settings jsonb,
    CONSTRAINT chk_content_type CHECK (((((platform)::text = 'linkedin'::text) AND ((content_type)::text = ANY ((ARRAY['post'::character varying, 'article'::character varying, 'video'::character varying, 'audio_event'::character varying])::text[]))) OR (((platform)::text = 'twitter'::text) AND ((content_type)::text = ANY ((ARRAY['tweet'::character varying, 'thread'::character varying, 'video'::character varying])::text[]))) OR (((platform)::text = 'instagram'::text) AND ((content_type)::text = ANY ((ARRAY['feed_post'::character varying, 'story'::character varying, 'reel'::character varying, 'igtv'::character varying])::text[]))) OR (((platform)::text = 'youtube'::text) AND ((content_type)::text = ANY ((ARRAY['video'::character varying, 'short'::character varying, 'live'::character varying])::text[]))) OR (((platform)::text = 'facebook'::text) AND ((content_type)::text = ANY ((ARRAY['post'::character varying, 'story'::character varying, 'video'::character varying, 'event'::character varying])::text[]))))),
    CONSTRAINT chk_facebook_content CHECK ((((platform)::text <> 'facebook'::text) OR (length(content) <= 63206))),
    CONSTRAINT chk_hashtag_limits CHECK (((((platform)::text = 'linkedin'::text) AND (array_length(hashtags, 1) <= 5)) OR (((platform)::text = 'twitter'::text) AND (array_length(hashtags, 1) <= 2)) OR (((platform)::text = 'instagram'::text) AND (array_length(hashtags, 1) <= 30)) OR (((platform)::text = 'youtube'::text) AND (array_length(hashtags, 1) <= 15)) OR (((platform)::text = 'facebook'::text) AND (array_length(hashtags, 1) <= 30)) OR (hashtags IS NULL))),
    CONSTRAINT chk_instagram_content CHECK ((((platform)::text <> 'instagram'::text) OR (length(content) <= 2200))),
    CONSTRAINT chk_linkedin_content CHECK ((((platform)::text <> 'linkedin'::text) OR (length(content) <= 3000))),
    CONSTRAINT chk_media_limits CHECK (((((platform)::text = 'linkedin'::text) AND (array_length(media_urls, 1) <= 9)) OR (((platform)::text = 'twitter'::text) AND (array_length(media_urls, 1) <= 4)) OR (((platform)::text = 'instagram'::text) AND (array_length(media_urls, 1) <= 10)) OR (((platform)::text = 'youtube'::text) AND (array_length(media_urls, 1) <= 1)) OR (((platform)::text = 'facebook'::text) AND (array_length(media_urls, 1) <= 12)) OR (media_urls IS NULL))),
    CONSTRAINT chk_platform CHECK (((platform)::text = ANY ((ARRAY['linkedin'::character varying, 'twitter'::character varying, 'instagram'::character varying, 'youtube'::character varying, 'facebook'::character varying])::text[]))),
    CONSTRAINT chk_status CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'scheduled'::character varying, 'publishing'::character varying, 'published'::character varying, 'failed'::character varying, 'cancelled'::character varying, 'blocked'::character varying])::text[]))),
    CONSTRAINT chk_twitter_content CHECK ((((platform)::text <> 'twitter'::text) OR (length(content) <= 280))),
    CONSTRAINT chk_video_duration CHECK (((video_duration IS NULL) OR (video_duration > 0))),
    CONSTRAINT chk_youtube_content CHECK ((((platform)::text <> 'youtube'::text) OR (length(content) <= 5000)))
);


