 SELECT t.id,
    t.organization_id,
    t.user_id,
    t.action_key,
    t.source_type,
    t.provider_name,
    t.model_name,
    t.input_tokens,
    t.output_tokens,
    t.total_tokens,
    t.api_cost_usd,
    t.credits_charged,
    t.credits_value_usd,
    t.margin_usd,
    t.retry_attempt,
    t.final_attempt,
    t.error_flag,
    t.error_type,
    t.reference_type,
    t.reference_id,
    t.pricing_snapshot,
    t.metadata,
    t.created_at,
    a.anomaly_type,
    a.severity AS anomaly_severity,
    a.detected_at AS anomaly_detected_at,
    a.metadata AS anomaly_metadata
   FROM (public.unified_transactions t
     LEFT JOIN LATERAL ( SELECT a_1.anomaly_type,
            a_1.severity,
            a_1.detected_at,
            a_1.metadata
           FROM public.cost_anomalies a_1
          WHERE ((a_1.organization_id = t.organization_id) AND ((a_1.action_key IS NULL) OR (a_1.action_key = t.action_key)) AND ((a_1.model_name IS NULL) OR (a_1.model_name = t.model_name)) AND ((a_1.detected_at >= (t.created_at - '00:00:05'::interval)) AND (a_1.detected_at <= (t.created_at + '00:00:05'::interval))))
          ORDER BY (abs(EXTRACT(epoch FROM (a_1.detected_at - t.created_at))))
         LIMIT 1) a ON (true));


