);


--
-- Name: COLUMN users.company_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.company_id IS 'DEPRECATED — use active_company_id. This column is frozen and no longer updated.';


--
-- Name: COLUMN users.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.status IS 'Operational lifecycle state. invited=admin-created, awaiting first auth/password; active=normal; suspended=blocked but recoverable; deleted=mirrors is_deleted. Distinct from onboarding_state, which tracks the signup-flow stage.';


--
-- Name: COLUMN users.session_revoked_after; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.session_revoked_after IS 'The JWT epoch. Any Supabase access token whose iat (issued-at) predates this value is rejected by the canonical auth resolver, even if the JWT signature is still valid. Bumped on suspend / force-logout / company-disable. Default NULL = no revocation has ever occurred for this user.';


--
-- Name: COLUMN users.activated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.activated_at IS 'Timestamp of the invited → active lifecycle transition. Written exactly once, when sync-supabase-user observes a status=invited row completing its first authenticated Supabase session. NULL on rows that pre-date this migration; NULL on rows that were never in the invited state (direct self-signup / admin-bootstrapped active accounts).';


--
-- Name: v_approval_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_approval_health AS
 SELECT organization_id,
    count(*) FILTER (WHERE (status = 'pending'::text)) AS pending_count,
    count(*) FILTER (WHERE (status = 'approved'::text)) AS approved_count,
    count(*) FILTER (WHERE (status = 'rejected'::text)) AS rejected_count,
    count(*) FILTER (WHERE (status = 'executed'::text)) AS executed_count,
    count(*) FILTER (WHERE (status = 'expired'::text)) AS expired_count,
    max(EXTRACT(epoch FROM (now() - proposed_at))) FILTER (WHERE (status = 'pending'::text)) AS oldest_pending_age_s
   FROM public.credit_action_approvals
  WHERE (proposed_at >= (now() - '30 days'::interval))
  GROUP BY organization_id;


--
-- Name: v_billing_operations_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_billing_operations_health AS
 SELECT organization_id,
    count(*) AS total_ops_24h,
    count(*) FILTER (WHERE (status = 'confirmed'::text)) AS confirmed_24h,
    count(*) FILTER (WHERE (status = 'released'::text)) AS released_24h,
    count(*) FILTER (WHERE (status = 'insufficient'::text)) AS insufficient_24h,
    count(*) FILTER (WHERE (status = 'error'::text)) AS errored_24h,
    count(*) FILTER (WHERE (status = 'duplicate'::text)) AS duplicate_24h,
    max(started_at) AS last_op_at
   FROM public.billing_operations
  WHERE (started_at >= (now() - '24:00:00'::interval))
  GROUP BY organization_id;


--
-- Name: v_company_financial_timeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_company_financial_timeline AS
 SELECT credit_transactions.organization_id,
    credit_transactions.created_at AS event_at,
    'ledger'::text AS event_kind,
    jsonb_build_object('transaction_id', credit_transactions.id, 'execution_phase', credit_transactions.execution_phase, 'credits_delta', credit_transactions.credits_delta, 'reference_type', credit_transactions.reference_type, 'reference_id', credit_transactions.reference_id, 'idempotency_key', credit_transactions.idempotency_key, 'usd_equivalent', credit_transactions.usd_equivalent) AS payload
   FROM public.credit_transactions
UNION ALL
 SELECT admin_financial_audit_events.organization_id,
    admin_financial_audit_events.created_at AS event_at,
    'admin_audit'::text AS event_kind,
    jsonb_build_object('audit_id', admin_financial_audit_events.id, 'action_type', admin_financial_audit_events.action_type, 'amount', admin_financial_audit_events.amount_credits, 'reason', admin_financial_audit_events.reason, 'approval_id', admin_financial_audit_events.approval_id, 'actor', admin_financial_audit_events.actor_user_id) AS payload
   FROM public.admin_financial_audit_events
UNION ALL
 SELECT credit_action_approvals.organization_id,
    credit_action_approvals.proposed_at AS event_at,
    'approval'::text AS event_kind,
    jsonb_build_object('approval_id', credit_action_approvals.id, 'status', credit_action_approvals.status, 'action_type', credit_action_approvals.action_type, 'proposed_by', credit_action_approvals.proposed_by, 'amount', ((credit_action_approvals.payload ->> 'amountCredits'::text))::numeric) AS payload
   FROM public.credit_action_approvals
UNION ALL
 SELECT payment_transactions.organization_id,
    payment_transactions.occurred_at AS event_at,
    'payment'::text AS event_kind,
    jsonb_build_object('payment_id', payment_transactions.id, 'provider', payment_transactions.provider, 'amount', payment_transactions.amount, 'currency', payment_transactions.currency, 'status', payment_transactions.status) AS payload
   FROM public.payment_transactions;


--
-- Name: v_finance_role_holders; Type: VIEW; Schema: public; Owner: -
