    created_at
   FROM public.user_company_roles
  WHERE ((role = ANY (ARRAY['FINANCE_ADMIN'::text, 'FINANCE_APPROVER'::text, 'FINANCE_AUDITOR'::text])) AND (status = 'active'::text));


--
-- Name: v_pricing_catalog; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pricing_catalog AS
 SELECT apc.action_key,
    apc.credit_cost,
    apc.cost_multiplier,
    apc.minimum_charge_usd,
    apc.ceiling_usd,
    apc.is_active,
    apc.effective_from,
    COALESCE(ccc.smart_dedup_seconds, 0) AS smart_dedup_seconds,
    apc.updated_at
   FROM (public.action_pricing_config apc
     LEFT JOIN public.credit_cost_config ccc ON ((ccc.action_type = apc.action_key)))
  WHERE (apc.is_active = true);


--
-- Name: v_reservation_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_reservation_health AS
 SELECT h.organization_id,
    count(*) AS open_holds,
    count(*) FILTER (WHERE (h.created_at < (now() - '01:00:00'::interval))) AS holds_older_1h,
    count(*) FILTER (WHERE (h.created_at < (now() - '06:00:00'::interval))) AS holds_older_6h,
    count(*) FILTER (WHERE (h.created_at < (now() - '24:00:00'::interval))) AS holds_older_24h,
    sum(abs(((h.free_delta + h.incentive_delta) + h.paid_delta))) AS total_reserved
   FROM ((public.credit_transactions h
     LEFT JOIN public.credit_transactions c ON (((c.parent_transaction_id = h.id) AND (c.execution_phase = 'confirm'::text))))
     LEFT JOIN public.credit_transactions r ON (((r.parent_transaction_id = h.id) AND (r.execution_phase = 'release'::text))))
  WHERE ((h.execution_phase = 'hold'::text) AND (c.id IS NULL) AND (r.id IS NULL))
  GROUP BY h.organization_id;


