--
-- Name: vw_company_report_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_company_report_stats AS
 SELECT company_id,
    count(*) AS total_reports,
    count(*) FILTER (WHERE (is_free = true)) AS free_reports,
    count(*) FILTER (WHERE (is_free = false)) AS paid_reports,
    count(*) FILTER (WHERE ((status)::text = 'completed'::text)) AS completed_reports,
    count(*) FILTER (WHERE ((status)::text = 'failed'::text)) AS failed_reports,
    count(*) FILTER (WHERE ((status)::text = 'generating'::text)) AS generating_reports,
    max(created_at) AS latest_report_at
   FROM public.reports
  GROUP BY company_id;


--
-- Name: vw_feature_completion_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_feature_completion_summary AS
 SELECT company_id,
    count(*) AS total_features,
    sum(
        CASE
            WHEN (status = 'completed'::text) THEN 1
            ELSE 0
        END) AS completed_count,
    sum(
        CASE
            WHEN (status = 'in_progress'::text) THEN 1
            ELSE 0
        END) AS in_progress_count,
    (((sum(
        CASE
            WHEN (status = 'completed'::text) THEN 1
            ELSE 0
        END))::numeric / (count(*))::numeric) * (100)::numeric) AS completion_percentage
   FROM public.feature_completion
  GROUP BY company_id;


--
-- Name: vw_free_reports_by_domain; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_free_reports_by_domain AS
 SELECT domain,
    count(*) AS free_report_count,
    max(created_at) AS latest_free_report_at
   FROM public.reports
  WHERE (is_free = true)
  GROUP BY domain;


