--
-- Name: weekly_alignment_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.weekly_alignment_summary AS
 SELECT c.id AS campaign_id,
    c.name AS campaign_name,
    cp.week_number,
    cp.theme,
    cp.focus_area,
    cp.alignment_status,
    count(cp.id) AS total_content_items,
    count(*) FILTER (WHERE ((cp.status)::text = 'published'::text)) AS published_content,
    count(*) FILTER (WHERE ((cp.alignment_status)::text = 'aligned'::text)) AS aligned_content,
    count(*) FILTER (WHERE ((cp.alignment_status)::text = 'needs-adjustment'::text)) AS needs_adjustment_content,
    array_remove(array_agg(DISTINCT cp.platform), NULL::character varying) AS platforms,
    array_remove(array_agg(DISTINCT cp.content_type), NULL::character varying) AS content_types
   FROM (public.campaigns c
     LEFT JOIN public.content_plans cp ON ((c.id = cp.campaign_id)))
  WHERE (cp.week_number IS NOT NULL)
  GROUP BY c.id, c.name, cp.week_number, cp.theme, cp.focus_area, cp.alignment_status;


