    week_number integer NOT NULL,
    theme character varying(255) NOT NULL,
    focus_area text NOT NULL,
    original_content jsonb NOT NULL,
    ai_enhanced_content jsonb DEFAULT '{}'::jsonb,
    manually_edited_content jsonb DEFAULT '{}'::jsonb,
    finalized_content jsonb NOT NULL,
    refinement_status character varying(50) DEFAULT 'draft'::character varying,
    ai_enhancement_applied boolean DEFAULT false,
    manual_edits_applied boolean DEFAULT false,
    finalized boolean DEFAULT false,
    daily_plan_populated boolean DEFAULT false,
    ai_enhancement_notes text,
    manual_edit_notes text,
    finalization_notes text,
    enhanced_by uuid,
    edited_by uuid,
    finalized_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    finalized_at timestamp with time zone,
    voice_notes jsonb DEFAULT '[]'::jsonb,
    content_items jsonb DEFAULT '[]'::jsonb,
    ai_enhanced boolean DEFAULT false,
    phase character varying(100),
    key_messaging text,
    content_types text[],
    platform_strategy jsonb,
    call_to_action text,
    target_metrics jsonb,
    content_guidelines text,
    hashtag_suggestions text[],
    completion_percentage integer DEFAULT 0,
    focus_areas text[],
    week_start_date date,
    twelve_week_plan_id uuid,
    assigned_to_user_id uuid,
    assigned_by_user_id uuid,
    status character varying(50) DEFAULT 'not_started'::character varying,
    completed_at timestamp with time zone,
    notes text,
    CONSTRAINT weekly_content_refinements_refinement_status_check CHECK (((refinement_status)::text = ANY ((ARRAY['draft'::character varying, 'ai-enhanced'::character varying, 'manually-edited'::character varying, 'finalized'::character varying, 'daily-populated'::character varying])::text[])))
);


