--

COMMENT ON COLUMN public.weekly_content_refinements.assigned_to_user_id IS 'Team member assigned to work on this week';


--
-- Name: weekly_refinement_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.weekly_refinement_status AS
 SELECT c.id AS campaign_id,
    c.name AS campaign_name,
    wcr.week_number,
    wcr.theme,
    wcr.focus_area,
    wcr.refinement_status,
    wcr.ai_enhancement_applied,
    wcr.manual_edits_applied,
    wcr.finalized,
    wcr.daily_plan_populated,
    count(DISTINCT cp.id) AS total_content_items,
    count(DISTINCT dcp.id) AS daily_plans_generated,
    wcr.created_at,
    wcr.finalized_at
   FROM (((public.campaigns c
     LEFT JOIN public.weekly_content_refinements wcr ON ((c.id = wcr.campaign_id)))
     LEFT JOIN public.content_plans cp ON (((c.id = cp.campaign_id) AND (cp.week_number = wcr.week_number))))
     LEFT JOIN public.daily_content_plans dcp ON (((c.id = dcp.campaign_id) AND (dcp.week_number = wcr.week_number))))
  GROUP BY c.id, c.name, wcr.week_number, wcr.theme, wcr.focus_area, wcr.refinement_status, wcr.ai_enhancement_applied, wcr.manual_edits_applied, wcr.finalized, wcr.daily_plan_populated, wcr.created_at, wcr.finalized_at;


