-- Name: reports only_admin_can_create_free_reports; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY only_admin_can_create_free_reports ON public.reports FOR INSERT WITH CHECK (((is_free = false) OR ((is_free = true) AND (auth.uid() IN ( SELECT user_company_roles.user_id
   FROM public.user_company_roles
  WHERE ((user_company_roles.company_id = reports.company_id) AND (user_company_roles.role = 'COMPANY_ADMIN'::text) AND (user_company_roles.status = 'active'::text)))))));


